const H2_AV_ARROW: u32 = 0xffd7_ab92; // the 환경설정 window's scroll arrows

pub const H2_AV_TEXT_AVATAR: &[u8] = b"\xbe\xc6\xb9\xd9\xc5\xb8"; // 아바타
const H2_AV_TEXT_EMPTY: &[u8] = b"\xbe\xc6\xb9\xd9\xc5\xb8\xb0\xa1\x20\xbe\xf8\xbd\xc0\xb4\xcf\xb4\xd9"; // 아바타가 없습니다
