    /// The field menu at 452x245 (panel (166,64), probe-measured): row 3 = SKILL.
    #[test]
    fn a_tap_on_a_menu_row_focuses_it_and_a_second_tap_is_ok() {
        let h2 = h2();
        let mut m = Mem::new();
        let state = match GuestBuild::Hero2Ktf.app_state() {
            Some(AppState::Absolute { addr, window, .. }) => (addr, window),
            _ => unreachable!(),
        };
        m.u32(state.0, state.1);
        m.u32(h2.menu_origin.0, 166);
        m.u32(h2.menu_origin.1, 64);
        m.u32(h2.menu_slot, 0x4843_0000);
        m.object(0x4843_0000, 0x4980_0000, 0x19_5000, h2.classes.field_menu);
        m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, 0);
        m.put(0x4980_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[0]);
        m.put(0x4980_0000 + 4 + Hero2Java::WIN_ROWS_OFF, &[8]);
        let r = m.reader();
        // Row 3 spans y = 64+12+36-1 .. +12 = 111..123
        match h2_tap(&r, &h2, 226, 116, 0) {
            H2Tap::Focus { writes } => {
                assert_eq!(writes[0], (0x4980_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![3]));
                assert_eq!(writes.len(), 2, "cursor + one repaint flag");
            }
            other => panic!("{other:?}"),
        }
        // The focused row (0) tapped again = OK.
        assert_eq!(h2_tap(&r, &h2, 226, 80, 0), H2Tap::Activate);
        // Below the last row but inside the panel: swallowed; outside the panel: nothing.
        assert_eq!(h2_tap(&r, &h2, 226, 64 + 12 + 96 + 5, 0), H2Tap::Swallow);
        assert_eq!(h2_tap(&r, &h2, 10, 10, 0), H2Tap::None);
        drop(r);
        // No window up: nothing.
        m.u32(state.0, 3);
        assert_eq!(h2_tap(&m.reader(), &h2, 226, 116, 0), H2Tap::None);
    }

    /// The other menu windows: a grid tap focuses / activates; unsupported → swallow.
    #[test]
    fn grid_windows_focus_by_cell() {
        let h2 = h2();
        let make = |class: u32, rows: u8, extra: &[(u32, Vec<u8>)]| -> Mem {
            let mut m = Mem::new();
            let state = match GuestBuild::Hero2Ktf.app_state() {
                Some(AppState::Absolute { addr, window, .. }) => (addr, window),
                _ => unreachable!(),
            };
            m.u32(state.0, state.1);
            m.u32(h2.menu_origin.0, 28);
            m.u32(h2.menu_origin.1, 51);
            m.u32(h2.screen.0, 176);
            m.u32(h2.screen.1, 220);
            m.u32(h2.screen.2, 88);
            m.u32(h2.screen.3, 110);
            m.u32(h2.menu_slot, 0x4843_0000);
            m.object(0x4843_0000, 0x4980_0000, 0x19_5000, h2.classes.field_menu);
            m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, 0x4843_0100);
            m.object(0x4843_0100, 0x4980_1000, 0x19_5100, class);
            m.u32(0x4980_1000 + 4 + Hero2Java::WIN_CHILD_OFF, 0);
            m.put(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[0]);
            m.put(0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, &[rows]);
            for (off, bytes) in extra {
                m.put(0x4980_1000 + 4 + off, bytes);
            }
            m
        };
        let cur = 0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF;
        let focus_byte = |t: H2Tap| match t {
            H2Tap::Focus { writes } => writes.iter().find(|(a, _)| *a == cur).map(|(_, b)| b[0]),
            _ => None,
        };
        // INVENTORY: cell (col 3, row 2) = h 17 at (28+7+45, 51+31+30) = (80, 112)
        let m = make(h2.classes.inventory_window, 28, &[]);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 86, 118, 0)), Some(17));
        assert_eq!(h2_tap(&m.reader(), &h2, 34, 84, 0), H2Tap::Activate, "cell 0 is the cursor");
        // STATUS without points: swallowed; with points: cell (col 2, row 1) = h 5 at (28+5+74, 51+91+12)
        let m = make(h2.classes.status_window, 5, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 110, 160, 0), H2Tap::Swallow);
        let m = make(h2.classes.status_window, 5, &[(Hero2Java::STATUS_HAS_POINTS_OFF, vec![1, 0, 0, 0])]);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 115, 146, 0)), Some(2), "row 0 col 2 (x 28+5+74=107..141, y 142..155)");
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 80, 158, 0)), Some(4), "row 1 col 1");
        assert_eq!(h2_tap(&m.reader(), &h2, 115, 158, 0), H2Tap::Swallow, "five stats: row 1 has no third cell");
        // EQUIPMENT: h 6 at (28+54, 51+56) = (82, 107)
        let m = make(h2.classes.equip_window, 7, &[]);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 86, 111, 0)), Some(6));
        // BEAST with no beast: swallowed; with one: (col 1, row 1) = h 3 at (28+19+57, 51+69+19)
        let m = make(h2.classes.beast_window, 4, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 110, 140, 0), H2Tap::Swallow);
        let mut m = make(h2.classes.beast_window, 4, &[(Hero2Java::BEAST_OBJ_OFF, 0x4843_9000u32.to_le_bytes().to_vec())]);
        m.object(0x4843_9000, 0x4980_9000, 0x19_5300, h2.classes.beast);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 110, 142, 0)), Some(3));
        // SYSTEM: 4 rows centred on cy 110: top = 110 - 30 = 80; row 2 = 110..124, x 56..120
        let m = make(h2.classes.list_windows[0], 4, &[]);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 88, 115, 0)), Some(2));
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 85, 0), H2Tap::Activate);
        // CARD: cell (col 2, row 1) = h 7 at (28+19+34, 51+14+17) = (81, 82), 15 x 15.
        let m = make(h2.classes.card_window, 15, &[]);
        assert_eq!(focus_byte(h2_tap(&m.reader(), &h2, 88, 89, 0)), Some(7));
        assert_eq!(h2_tap(&m.reader(), &h2, 52, 70, 0), H2Tap::Activate, "cell 0 is the cursor");
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 150, 0), H2Tap::Swallow, "below the three rows");
        // QUEST: the arrow span (x+4..+38, y+16..+32) steps the quest, the body toggles.
        let m = make(h2.classes.quest_window, 3, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 38, 74, 0), H2Tap::Page { dir: 2 });
        assert_eq!(h2_tap(&m.reader(), &h2, 58, 74, 0), H2Tap::Page { dir: 3 });
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 120, 0), H2Tap::Page { dir: 0 });
        let m = make(h2.classes.quest_window, 1, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 58, 74, 0), H2Tap::Swallow, "one quest: nothing to step to");
        let m = make(h2.classes.quest_window, 0, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 120, 0), H2Tap::Activate, "no quest: OK closes it");
        // The detail window: anywhere on the panel = OK, off it = nothing.
        let m = make(h2.classes.detail_window, 0, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 100, 0), H2Tap::Activate);
        assert_eq!(h2_tap(&m.reader(), &h2, 5, 5, 0), H2Tap::None);
        // ★★ 2026-10-14 The ITEM detail window: an equipment record with option text turns its page on a tap in the text
        // box (28+21..+117, 51+15..+102) and closes elsewhere on the panel; without text (or an accessory) it is all OK.
        for (kind, desc, box_tap) in [(0u32, 0x4843_7000u32, H2Tap::Page { dir: 3 }), (9, 0x4843_7000, H2Tap::Page { dir: 3 }), (0, 0, H2Tap::Activate), (12, 0x4843_7000, H2Tap::Activate)] {
            let mut m = make(h2.classes.item_detail_window, 0, &[(AccessoryPatch::DETAIL_RECORD_OFF, 0x4843_6000u32.to_le_bytes().to_vec())]);
            m.object(0x4843_6000, 0x4980_6000, 0x19_5200, 0);
            m.u32(0x4980_6000 + 4 + AccessoryPatch::ITEM_TYPE_OFF, kind);
            m.u32(0x4980_6000 + 4 + AccessoryPatch::ITEM_DESC_OFF, desc);
            assert_eq!(h2_tap(&m.reader(), &h2, 88, 100, 0), box_tap, "type {kind} desc {desc:#x}: the text box");
            assert_eq!(h2_tap(&m.reader(), &h2, 88, 160, 0), H2Tap::Activate, "type {kind}: the footer closes");
            assert_eq!(h2_tap(&m.reader(), &h2, 5, 5, 0), H2Tap::None);
        }
        // An unknown window: swallowed on the panel.
        let m = make(0x19_2000, 3, &[]);
        assert_eq!(h2_tap(&m.reader(), &h2, 88, 100, 0), H2Tap::Swallow);
    }

    /// The SHELL chain: rooted at `t.a` while the state word is a shell value, with the
    /// title's own panel origin. Title box / arrows, the slot screen in both shapes, the
    /// OPTION rows and the HELP pager — all at 176x246 (`ax.j/k` = 88/123).
    /// ★★ 2026-10-15 (user: *"악의 실행하고 다음맵으로 넘어가면 악의가 풀리고있어"*): 악의's world is a character in a running game —
    /// the map change's state 1 (no title singleton) is IN, the title shell (state 1 · 2 with `t.a`) and no character are OUT,
    /// and the plan keeps STATE · LOOK through the map change where the old 「in game」 answer wrote STATE 0.
    #[test]
    fn the_demon_stays_through_a_map_change_and_ends_at_the_shell() {
        let h2 = h2();
        let addr = match GuestBuild::Hero2Ktf.app_state() {
            Some(AppState::Absolute { addr, .. }) => addr,
            _ => unreachable!(),
        };
        let world = |state: u32, title: u32, character: u32| {
            let mut m = Mem::new();
            m.u32(addr, state);
            m.u32(h2.title_slot, title);
            m.u32(h2.char_slot, character);
            let r = m.reader();
            h2_demon_in_world(&r, &h2)
        };
        let ch = 0x4843_0200;
        assert!(world(3, 0, ch), "the field");
        assert!(world(5, 0, ch) && world(4, 0, ch), "a window · a script box");
        assert!(world(1, 0, ch), "between two maps: state 1 with no title singleton");
        assert!(!world(1, 0x4843_0000, ch) && !world(2, 0x4843_0000, ch), "the slot list · the title");
        assert!(!world(3, 0, 0), "no character");
        // the plan: STATE 2 · LOOK 1 through the map change; out of the world (the shell) both down
        type P = DemonPatch;
        let through = h2_demon_look_plan(P::STATE_ON as i32, 1, Some(1), true, world(1, 0, ch), 300);
        assert_eq!((through.state, through.look), (None, None));
        assert_eq!(through.body, Some(P::COSTUME), "the demon body still wanted");
        let shell = h2_demon_look_plan(P::STATE_ON as i32, 1, Some(1), true, world(2, 0x4843_0000, ch), 300);
        assert_eq!((shell.state, shell.look), (Some(0), Some(false)));
    }

    #[test]
    fn a_tap_on_the_shell_is_routed_from_the_title_singleton() {
        let h2 = h2();
        let make = |top_class: Option<u32>, extra: &[(u32, Vec<u8>)]| -> Mem {
            let mut m = Mem::new();
            let addr = match GuestBuild::Hero2Ktf.app_state() {
                Some(AppState::Absolute { addr, .. }) => addr,
                _ => unreachable!(),
            };
            m.u32(addr, 2); // title
            m.u32(h2.title_origin.0, 28);
            m.u32(h2.title_origin.1, 65);
            m.u32(h2.screen.0, 176);
            m.u32(h2.screen.1, 246);
            m.u32(h2.screen.2, 88);
            m.u32(h2.screen.3, 123);
            m.u32(h2.title_slot, 0x4843_0000);
            m.object(0x4843_0000, 0x4980_0000, 0x19_5000, h2.classes.title_window);
            m.put(0x4980_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[1]);
            m.put(0x4980_0000 + 4 + Hero2Java::WIN_ROWS_OFF, &[9]);
            match top_class {
                None => m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, 0),
                Some(class) => {
                    m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, 0x4843_0100);
                    m.object(0x4843_0100, 0x4980_1000, 0x19_5100, class);
                    m.u32(0x4980_1000 + 4 + Hero2Java::WIN_CHILD_OFF, 0);
                    m.put(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[0]);
                    m.put(0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, &[3]);
                    for (off, bytes) in extra {
                        m.put(0x4980_1000 + 4 + off, bytes);
                    }
                }
            }
            m
        };
        // The menu chain is NOT walked on the shell even with a stale `bw.a`.
        let mut m = make(None, &[]);
        m.u32(h2.menu_slot, 0x4843_0000);
        assert_eq!(h2_window_chain(&m.reader(), &h2).map(|c| c[0].class), Some(h2.classes.title_window));
        // Title: box at (88, 123 + 61 − 12 = 172): inside = OK, ends = LEFT / RIGHT, else nothing.
        let r = m.reader();
        assert_eq!(h2_tap(&r, &h2, 88, 180, 0), H2Tap::Activate);
        assert_eq!(h2_tap(&r, &h2, 40, 180, 0), H2Tap::Page { dir: 2 });
        assert_eq!(h2_tap(&r, &h2, 130, 180, 0), H2Tap::Page { dir: 3 });
        assert_eq!(h2_tap(&r, &h2, 88, 120, 0), H2Tap::None, "the logo");
        assert_eq!(h2_tap(&r, &h2, 10, 180, 0), H2Tap::None, "past the arrows");
        // A state that is neither window nor shell: no chain at all.
        let mut m2 = make(None, &[]);
        m2.u32(match GuestBuild::Hero2Ktf.app_state() { Some(AppState::Absolute { addr, .. }) => addr, _ => unreachable!() }, 3);
        assert_eq!(h2_tap(&m2.reader(), &h2, 88, 180, 0), H2Tap::None);
        // Slot screen, mode 1: box top at 123 − 10 = 113.
        let m = make(Some(h2.classes.slot_window), &[(Hero2Java::SLOT_MODE_OFF, vec![1])]);
        let r = m.reader();
        assert_eq!(h2_tap(&r, &h2, 88, 120, 0), H2Tap::Activate);
        assert_eq!(h2_tap(&r, &h2, 130, 120, 0), H2Tap::Page { dir: 3 });
        assert_eq!(h2_tap(&r, &h2, 88, 180, 0), H2Tap::None, "the title's box is not here");
        // Mode 11 (class pick): box top at 123 − 25 = 98.
        let m = make(Some(h2.classes.slot_window), &[(Hero2Java::SLOT_MODE_OFF, vec![11])]);
        let r = m.reader();
        assert_eq!(h2_tap(&r, &h2, 88, 105, 0), H2Tap::Activate);
        assert_eq!(h2_tap(&r, &h2, 40, 105, 0), H2Tap::Page { dir: 2 });
        assert_eq!(h2_tap(&r, &h2, 88, 125, 0), H2Tap::None);
        // OPTION: rows at 123 − 36 + 18·i, x 38 .. 160. Row 0 is the cursor → RIGHT; row 1 → focus.
        let m = make(Some(h2.classes.option_window), &[]);
        let r = m.reader();
        assert_eq!(h2_tap(&r, &h2, 100, 90, 0), H2Tap::Page { dir: 3 }, "the focused row cycles its value");
        match h2_tap(&r, &h2, 100, 105, 0) {
            H2Tap::Focus { writes } => assert_eq!(writes[0], (0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![1])),
            other => panic!("{other:?}"),
        }
        assert_eq!(h2_tap(&r, &h2, 100, 200, 0), H2Tap::None, "below the five rows");
        assert_eq!(h2_tap(&r, &h2, 20, 90, 0), H2Tap::None, "left of the labels");
        // HELP on the shell: header at 123 − 36 = 87, arrows at 88 ± 50; body scrolls.
        let m = make(Some(h2.classes.help_window), &[]);
        let r = m.reader();
        assert_eq!(h2_tap(&r, &h2, 40, 90, 0), H2Tap::Page { dir: 2 });
        assert_eq!(h2_tap(&r, &h2, 138, 90, 0), H2Tap::Page { dir: 3 });
        assert_eq!(h2_tap(&r, &h2, 88, 90, 0), H2Tap::Swallow, "the title text");
        assert_eq!(h2_tap(&r, &h2, 88, 120, 0), H2Tap::Page { dir: 0 });
        assert_eq!(h2_tap(&r, &h2, 88, 180, 0), H2Tap::Page { dir: 1 });
        assert_eq!(h2_tap(&r, &h2, 88, 60, 0), H2Tap::None, "above the pager");
    }

    /// The inventory walk: `ag.a` → `bq` → Vector → `ch` records, with the heal index.
    #[test]
    fn the_inventory_walk_reads_records_and_the_heal_index() {
        let h2 = h2();
        let mut m = Mem::new();
        m.u32(h2.inventory_slot, 0x4843_0000);
        m.object(0x4843_0000, 0x4980_0000, 0x19_5000, 0x19_2844);
        m.put(0x4980_0000 + 4 + Hero2Java::INV_B_OFF, &[28]);
        m.put(0x4980_0000 + 4 + Hero2Java::INV_HEAL_OFF, &[1]);
        m.put(0x4980_0000 + 4 + Hero2Java::INV_C_OFF, &[1]);
        m.u32(0x4980_0000 + 4 + Hero2Java::INV_VECTOR_OFF, 0x4843_0100);
        // The Vector: elementData (an Object[] of capacity 4) + elementCount 2.
        m.object(0x4843_0100, 0x4980_1000, 0x19_5100, 0);
        m.u32(0x4980_1000 + 4 + Hero2Java::VECTOR_DATA_OFF, 0x4843_0200);
        m.u32(0x4980_1000 + 4 + Hero2Java::VECTOR_COUNT_OFF, 2);
        m.object(0x4843_0200, 0x4980_2000, 0x19_5200, 0);
        m.u32(0x4980_2000 + 4, 4);
        m.u32(0x4980_2000 + 8, 0x4843_0300);
        m.u32(0x4980_2000 + 12, 0x4843_0400);
        // Two records: 포도주 x87 (type 26) and 하이포션 x99 (type 25, the heal).
        for (k, (handle, fields, kind, count, name)) in [(0x4843_0300u32, 0x4980_3000u32, 26i8, 87u32, b"\xc6\xf7\xb5\xb5\xc1\xd6".as_slice()), (0x4843_0400, 0x4980_4000, 25, 99, b"\xc7\xcf\xc0\xcc\xc6\xf7\xbc\xc7")].into_iter().enumerate() {
            m.object(handle, fields, 0x19_5300 + k as u32 * 0x100, 0x19_2aa8);
            m.put(fields + 4 + Hero2Java::ITEM_TYPE_OFF, &[kind as u8]);
            m.put(fields + 4 + Hero2Java::ITEM_ID_OFF, &[0]);
            m.u32(fields + 4 + Hero2Java::ITEM_COUNT_OFF, count);
            m.u32(fields + 4 + Hero2Java::ITEM_D_OFF, 600);
            let nh = 0x4843_0500 + k as u32 * 0x100;
            m.u32(fields + 4 + Hero2Java::ITEM_NAME_OFF, nh);
            m.object(nh, 0x4980_5000 + k as u32 * 0x100, 0x19_5500, 0);
            m.u32(0x4980_5000 + k as u32 * 0x100 + 4, name.len() as u32);
            m.put(0x4980_5000 + k as u32 * 0x100 + 8, name);
        }
        let inv = h2_inventory(&m.reader(), &h2).expect("inventory");
        assert_eq!((inv.b, inv.heal, inv.c), (28, 1, 1));
        assert_eq!(inv.heal_addr(), 0x4980_0000 + 4 + Hero2Java::INV_HEAL_OFF);
        assert_eq!(inv.items.len(), 2);
        assert_eq!((inv.items[0].kind, inv.items[0].count, inv.items[0].d), (26, 87, 600));
        assert_eq!((inv.items[1].kind, inv.items[1].count), (25, 99));
        assert_eq!(inv.items[1].name, b"\xc7\xcf\xc0\xcc\xc6\xf7\xbc\xc7".to_vec());
        assert!(Hero2Java::ITEM_TYPE_RECOVERY.contains(&inv.items[0].kind) && !Hero2Java::ITEM_TYPE_RECOVERY.contains(&29));
        // No inventory on the shell / before boot.
        assert!(h2_inventory(&Mem::new().reader(), &h2).is_none());
    }

    /// A bag the host holds by handle, `kinds` records deep, for the warehouse tests:
    /// `bq` -> Vector(count = kinds.len(), capacity 8) -> `ch` records with only the type
    /// byte set. Returns `(bag handle, elementData base, record handles)`.
    fn bag_of_kinds(m: &mut Mem, kinds: &[i8]) -> (u32, u32, Vec<u32>) {
        let (bag, bf) = (0x4a00_0000u32, 0x4a00_1000u32);
        m.object(bag, bf, 0x19_5000, 0x19_2844);
        m.put(bf + 4 + Hero2Java::INV_B_OFF, &[Hero2Java::BAG_CAPACITY as u8]);
        m.put(bf + 4 + Hero2Java::INV_HEAL_OFF, &[0]);
        m.put(bf + 4 + Hero2Java::INV_C_OFF, &[0]);
        let (vec, vf) = (0x4a00_2000u32, 0x4a00_3000u32);
        m.u32(bf + 4 + Hero2Java::INV_VECTOR_OFF, vec);
        m.object(vec, vf, 0x19_5100, 0);
        let (data, df) = (0x4a00_4000u32, 0x4a00_5000u32);
        m.u32(vf + 4 + Hero2Java::VECTOR_DATA_OFF, data);
        m.u32(vf + 4 + Hero2Java::VECTOR_COUNT_OFF, kinds.len() as u32);
        m.object(data, df, 0x19_5200, 0);
        m.u32(df + 4, 8);
        let mut recs = Vec::new();
        for (k, kind) in kinds.iter().enumerate() {
            let (rh, rf) = (0x4a01_0000 + k as u32 * 0x100, 0x4a02_0000 + k as u32 * 0x100);
            m.object(rh, rf, 0x19_5300, 0x19_2aa8);
            m.put(rf + 4 + Hero2Java::ITEM_TYPE_OFF, &[*kind as u8]);
            m.put(rf + 4 + Hero2Java::ITEM_ID_OFF, &[0]);
            m.u32(rf + 4 + Hero2Java::ITEM_COUNT_OFF, 1);
            m.u32(df + 8 + k as u32 * 4, rh);
            recs.push(rh);
        }
        (bag, df + 8, recs)
    }

    /// 2026-09-24: the 재료가방 (type 29) belongs in cell 0 of the ACCOUNT warehouse. An
    /// older blob has it last (or not at all, and the host's append puts it last), so the
    /// host rotates the Vector's slots: same handles, same count, new order.
    #[test]
    fn the_warehouse_front_writes_rotate_the_slots_and_change_nothing_else() {
        let mut m = Mem::new();
        let (bag, base, recs) = bag_of_kinds(&mut m, &[5, 7, Hero2Java::ITEM_TYPE_MATERIAL_BAG, 12]);
        let r = m.reader();
        assert_eq!(h2_bag_index_of_kind(&r, bag, Hero2Java::ITEM_TYPE_MATERIAL_BAG), Some(2));
        assert_eq!(h2_bag_index_of_kind(&r, bag, 12), Some(3));
        assert_eq!(h2_bag_index_of_kind(&r, bag, 1), None, "no such type");
        // Rotate [5, 7, 29, 12] -> [29, 5, 7, 12]: slots 0..=2 written, slot 3 untouched.
        let w = h2_bag_front_writes(&r, bag, 2).expect("writes");
        assert_eq!(w, vec![(base, recs[2].to_le_bytes()), (base + 4, recs[0].to_le_bytes()), (base + 8, recs[1].to_le_bytes())]);
        // Apply them to the fake heap and read the bag back as the game would.
        let mut m2 = Mem::new();
        bag_of_kinds(&mut m2, &[5, 7, Hero2Java::ITEM_TYPE_MATERIAL_BAG, 12]);
        for (a, b) in &w {
            m2.put(*a, b);
        }
        let after = h2_bag_of(&m2.reader(), bag).expect("bag");
        assert_eq!(after.items.iter().map(|i| i.kind).collect::<Vec<_>>(), vec![Hero2Java::ITEM_TYPE_MATERIAL_BAG, 5, 7, 12]);
        assert_eq!(after.items.iter().map(|i| i.handle).collect::<Vec<_>>(), vec![recs[2], recs[0], recs[1], recs[3]], "the same four objects");
        assert_eq!(h2_bag_index_of_kind(&m2.reader(), bag, Hero2Java::ITEM_TYPE_MATERIAL_BAG), Some(0));
        // Already first: nothing to write. Past the end: refused, not clamped.
        assert_eq!(h2_bag_front_writes(&r, bag, 0), Some(vec![]));
        assert_eq!(h2_bag_front_writes(&r, bag, 4), None);
        // A slot that is not a live handle inside the rotated range: refused whole, so a
        // half-rotation can never drop a record.
        let mut m3 = Mem::new();
        let (bag3, base3, _) = bag_of_kinds(&mut m3, &[5, 7, Hero2Java::ITEM_TYPE_MATERIAL_BAG]);
        m3.u32(base3 + 4, 0);
        assert_eq!(h2_bag_front_writes(&m3.reader(), bag3, 2), None);
        assert!(h2_bag_front_writes(&Mem::new().reader(), bag, 1).is_none(), "no bag at all");
    }

    /// ★ 2026-10-13 (user: *"제련석을 1개 1개 1개 1개 계정창고에 넣으면 계정창고에 4칸을 차지하게 되는데 이걸 제련석 1칸에
    /// 4개 가 되도록"*): a stack moves through the game's merge, and the warehouse load folds the cells the old object
    /// move left — the record it folds next is the first one an EARLIER stack of the same `(type, id)` has room for.
    #[test]
    fn the_fold_picks_the_first_record_an_earlier_stack_has_room_for() {
        assert!(h2_move_merges(20) && h2_move_merges(24) && h2_move_merges(23) && h2_move_merges(34), "제련석 · 포션 · 재료 · 카드 stack");
        assert!(!h2_move_merges(5) && !h2_move_merges(0) && !h2_move_merges(12) && !h2_move_merges(Hero2Java::ITEM_TYPE_MATERIAL_BAG), "equipment and the 재료가방 move as the object they are");
        // (type, id, count) per cell → the index of the record to fold next
        let pick = |cells: &[(i8, i8, i32)]| -> Option<usize> {
            let mut m = Mem::new();
            let kinds: Vec<i8> = cells.iter().map(|c| c.0).collect();
            let (bag, _, recs) = bag_of_kinds(&mut m, &kinds);
            for (k, (_, id, count)) in cells.iter().enumerate() {
                let rf = 0x4a02_0000 + k as u32 * 0x100;
                m.put(rf + 4 + Hero2Java::ITEM_ID_OFF, &[*id as u8]);
                m.u32(rf + 4 + Hero2Java::ITEM_COUNT_OFF, *count as u32);
            }
            let got = h2_bag_merge_candidate(&m.reader(), bag)?;
            recs.iter().position(|r| *r == got.handle)
        };
        let m29 = Hero2Java::ITEM_TYPE_MATERIAL_BAG;
        assert_eq!(pick(&[(m29, 0, 1), (20, 0, 1), (20, 0, 1), (20, 0, 1), (20, 0, 1)]), Some(2), "the user's four 제련석: the second goes into the first");
        assert_eq!(pick(&[(20, 0, 4)]), None, "folded: one cell");
        assert_eq!(pick(&[(20, 0, 99), (20, 0, 5)]), None, "the earlier stack is full");
        assert_eq!(pick(&[(20, 0, 99), (20, 0, 5), (20, 0, 7)]), Some(2), "past a full one, the next with room");
        assert_eq!(pick(&[(20, 0, 50), (21, 0, 3), (20, 0, 2)]), Some(2), "another kind between");
        assert_eq!(pick(&[(20, 0, 5), (20, 1, 5)]), None, "another id is another item");
        assert_eq!(pick(&[(5, 0, 1), (5, 0, 1)]), None, "two helmets are two helmets");
        assert_eq!(pick(&[(m29, 0, 1), (m29, 0, 1)]), None);
        assert_eq!(pick(&[(20, 0, 0), (20, 0, 3)]), None, "an empty record opens nothing");
        // an element that cannot be read: nothing is folded on a guess
        let mut m = Mem::new();
        let (bag, base, _) = bag_of_kinds(&mut m, &[20, 20]);
        m.u32(base + 4, 0);
        assert!(h2_bag_merge_candidate(&m.reader(), bag).is_none());
        assert!(h2_bag_merge_candidate(&Mem::new().reader(), bag).is_none(), "no bag at all");
    }

    /// The 예/아니오 popup (kind 2, one text line): buttons at cx ± …, 15 tall.
    #[test]
    fn the_confirm_popup_has_two_buttons() {
        let (mut m, _) = popup_world(6);
        let h2 = h2();
        m.u32(h2.screen.0, 176);
        m.u32(h2.screen.1, 220);
        m.u32(h2.screen.2, 88);
        m.u32(h2.screen.3, 110);
        m.u32(h2.menu_origin.0, 28);
        m.u32(h2.menu_origin.1, 51);
        m.put(0x4985_0000 + 4 + Hero2Java::POPUP_KIND_OFF, &[2]);
        m.put(0x4985_0000 + 4 + Hero2Java::WIN_ROWS_OFF, &[2]);
        m.u32(0x4985_0000 + 4 + Hero2Java::POPUP_HEIGHT_OFF, 16 * 3); // one line
        let r = m.reader();
        // top = (220-48)/2 = 86; buttons y = 86+12+16+1 = 115 .. 130; 예 x 44..86, 아니오 90..132
        assert_eq!(h2_tap(&r, &h2, 60, 120, 0), H2Tap::Activate, "예 is the cursor (h = 0)");
        match h2_tap(&r, &h2, 110, 120, 0) {
            H2Tap::Focus { writes } => assert_eq!(writes[0].1, vec![1]),
            other => panic!("{other:?}"),
        }
        assert_eq!(h2_tap(&r, &h2, 88, 95, 0), H2Tap::Swallow, "the text line");
    }

    /// The popup is modal: its rows focus / activate, everything else is swallowed.
    #[test]
    fn a_tap_on_the_popup_is_a_row_or_nothing() {
        let (mut m, _) = popup_world(6);
        let h2 = h2();
        m.u32(h2.menu_origin.0, 28);
        m.u32(h2.menu_origin.1, 51);
        m.u32(h2.screen.0, 176);
        m.u32(h2.screen.1, 220);
        let r = m.reader();
        // Box (51, 59, 74, 102); row 2 = y 59+6+32 .. +16 = 97..113
        match h2_tap(&r, &h2, 88, 100, 0) {
            H2Tap::Focus { writes } => {
                assert_eq!(writes[0], (0x4985_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![2]));
                assert_eq!(writes.len(), 1 + 3, "cursor + repaint of menu, window, popup");
            }
            other => panic!("{other:?}"),
        }
        assert_eq!(h2_tap(&r, &h2, 88, 70, 0), H2Tap::Activate, "row 0 is focused");
        assert_eq!(h2_tap(&r, &h2, 40, 100, 0), H2Tap::Swallow, "beside the box");
        assert_eq!(h2_tap(&r, &h2, 88, 40, 0), H2Tap::Swallow, "above the box, over the skill list");
    }

    /// The skill window (ACTIVE tab, class 로그: 4 + 2 cells) at 452x245.
    #[test]
    fn a_tap_on_a_skill_cell_or_the_tab_header() {
        let (mut m, _) = popup_world(6);
        let h2 = h2();
        // Close the popup: the skill window is the top.
        m.u32(0x4980_1000 + 4 + Hero2Java::WIN_CHILD_OFF, 0);
        m.put(0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, &[6]);
        m.put(0x4980_1000 + 4 + Hero2Java::SKILL_SPLIT_OFF, &[4]);
        m.put(0x4980_1000 + 4 + Hero2Java::SKILL_HEADER_OFF, &[0, 0, 0, 0]);
        m.put(h2.skill_static_b, &[4]);
        m.u32(h2.menu_origin.0, 166);
        m.u32(h2.menu_origin.1, 64);
        let r = m.reader();
        // Column 0, row 2 (급소가격): x = 166+5+15 = 186 .. 224, y = 64+12+38+10 = 124 .. 137
        match h2_tap(&r, &h2, 200, 130, 0) {
            H2Tap::Focus { writes } => assert_eq!(writes[0], (0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![2])),
            other => panic!("{other:?}"),
        }
        // Column 1, row 1 (`?`, h = 5): x = 166+5+57+15 = 243
        match h2_tap(&r, &h2, 260, 110, 0) {
            H2Tap::Focus { writes } => assert_eq!(writes[0], (0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![5])),
            other => panic!("{other:?}"),
        }
        // Cursor is 0: column 0 row 0 again = OK.
        assert_eq!(h2_tap(&r, &h2, 200, 90, 0), H2Tap::Activate);
        // The header at y = 64+112 = 176: left half → LEFT, right half → RIGHT, with the
        // header-focus write first.
        match h2_tap(&r, &h2, 180, 180, 0) {
            H2Tap::Tab { right, writes } => {
                assert!(!right);
                assert_eq!(writes[0], (0x4980_1000 + 4 + Hero2Java::SKILL_HEADER_OFF, 1u32.to_le_bytes().to_vec()));
            }
            other => panic!("{other:?}"),
        }
        assert!(matches!(h2_tap(&r, &h2, 225, 180, 0), H2Tap::Tab { right: true, .. }));
        // Column 1 has only two rows: a tap on its third row is swallowed, not clamped.
        assert_eq!(h2_tap(&r, &h2, 260, 130, 0), H2Tap::Swallow);
    }

    /// S7: state 5, menu → inventory window (main bag, cursor `cursor`) → popup kind 6
    /// with the three native labels = gm rows 30/31/28; the gm table with rows 28..35;
    /// the bag `bq` with a few records; the cycle `bq.j = [24, 25, 26]`.
    fn item_world(cursor: i8) -> (Mem, u32) {
        let h2 = h2();
        let mut m = Mem::new();
        let state = match GuestBuild::Hero2Ktf.app_state() {
            Some(AppState::Absolute { addr, window, .. }) => (addr, window),
            _ => unreachable!(),
        };
        m.u32(state.0, state.1);
        let (cls_menu, cls_inv, cls_popup) = (0x19_5000u32, 0x19_5300u32, 0x19_5200u32);
        m.u32(h2.menu_slot, 0x4843_0000);
        m.object(0x4843_0000, 0x4980_0000, cls_menu, h2.classes.field_menu);
        m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, 0x4843_0100);
        // inventory window over the MAIN bag
        m.object(0x4843_0100, 0x4980_1000, cls_inv, h2.classes.inventory_window);
        m.put(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[cursor as u8]);
        m.u32(0x4980_1000 + 4 + Hero2Java::INV_WIN_BAG_OFF, 0x4845_0000);
        m.u32(0x4980_1000 + 4 + Hero2Java::WIN_CHILD_OFF, 0x4843_0200);
        // popup kind 6, three rows
        m.object(0x4843_0200, 0x4985_0000, cls_popup, h2.classes.popup);
        m.put(0x4985_0000 + 4 + Hero2Java::POPUP_KIND_OFF, &[6]);
        m.put(0x4985_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[0]);
        m.put(0x4985_0000 + 4 + Hero2Java::WIN_ROWS_OFF, &[3]);
        m.u32(0x4985_0000 + 4 + Hero2Java::POPUP_HEIGHT_OFF, 54);
        m.u32(0x4985_0000 + 4 + Hero2Java::POPUP_LABELS_OFF, 0x4844_0000);
        m.u32(0x4844_0000, 0x4906_0000);
        m.u32(0x4906_0000 + 4, 3);
        // the gm table: `i.a` = byte[][] of 40 rows; rows 28..37 are real byte[]s
        m.u32(h2.gm_table_slot, 0x4846_0000);
        m.u32(0x4846_0000, 0x4907_0000);
        m.u32(0x4907_0000 + 4 + Hero2Java::TABLE_ROWS_OFF, 0x4846_0100);
        m.u32(0x4846_0100, 0x4908_0000);
        m.u32(0x4908_0000 + 4, 40);
        let gm_row = |i: u32| 0x4843_2000 + i * 0x10;
        for (i, text) in [(28u32, b"\xb9\xf6\xb8\xae\xb1\xe2".to_vec()), (30, b"\xbb\xe7\xbf\xeb\xc7\xcf\xb1\xe2".to_vec()), (31, b"\xbb\xf3\xbc\xbc\xba\xb8\xb1\xe2".to_vec()), (34, reg(0)), (35, reg(1)), (36, reg(2)), (37, reg(3))] {
            m.u32(0x4908_0000 + 8 + i * 4, gm_row(i));
            m.bytes(gm_row(i), 0x4909_0000 + i * 0x100, &text);
        }
        for (k, row) in [30u32, 31, 28].iter().enumerate() {
            m.u32(0x4906_0000 + 8 + k as u32 * 4, gm_row(*row));
        }
        // the bag: Vector of 3 records — [0] 포도주 26 ×87, [1] 하이포션 25 ×99, [2] 하이포션 25 ×42
        m.u32(h2.inventory_slot, 0x4845_0000);
        m.u32(0x4845_0000, 0x4990_0000);
        m.u32(0x4990_0000 + 4 + Hero2Java::INV_VECTOR_OFF, 0x4845_0100);
        m.put(0x4990_0000 + 4 + Hero2Java::INV_B_OFF, &[28]);
        m.put(0x4990_0000 + 4 + Hero2Java::INV_HEAL_OFF, &[1]);
        m.put(0x4990_0000 + 4 + Hero2Java::INV_C_OFF, &[1]);
        m.u32(0x4845_0100, 0x4990_1000);
        m.u32(0x4990_1000 + 4 + Hero2Java::VECTOR_DATA_OFF, 0x4845_0200);
        m.u32(0x4990_1000 + 4 + Hero2Java::VECTOR_COUNT_OFF, 3);
        m.u32(0x4845_0200, 0x4990_2000);
        m.u32(0x4990_2000 + 4, 4);
        for (i, (kind, id, count)) in [(26u8, 0u8, 87i32), (25, 0, 99), (25, 0, 42)].iter().enumerate() {
            let h = 0x4845_0300 + i as u32 * 0x10;
            let f = 0x4990_3000 + i as u32 * 0x100;
            m.u32(0x4990_2000 + 8 + i as u32 * 4, h);
            m.u32(h, f);
            m.put(f + 4 + Hero2Java::ITEM_TYPE_OFF, &[*kind]);
            m.put(f + 4 + Hero2Java::ITEM_ID_OFF, &[*id]);
            m.u32(f + 4 + Hero2Java::ITEM_COUNT_OFF, *count as u32);
        }
        // the cycle
        m.u32(h2.heal_cycle_slot, 0x4845_0400);
        m.bytes(0x4845_0400, 0x4990_4000, &[24, 25, 26]);
        (m, 0x4843_0200)
    }

    #[test]
    fn the_item_popup_walk_reads_the_record_and_the_native_shape() {
        let (m, handle) = item_world(1);
        let r = m.reader();
        let p = h2_item_popup_walk(&r, &h2(), (0, 0)).expect("walked");
        assert_eq!(p.handle, handle);
        assert_eq!((p.item_index, p.item_kind, p.item_id, p.item_count), (1, 25, 0, 99));
        assert_eq!(p.shape(), Some(true), "native three rows");
        assert!(p.bindable(&[24, 25, 26]));
        assert!(!p.bindable(&[24, 26]), "27 치료제-style: recovery but not in the cycle");
        // The skill walk does not claim this popup, and vice versa.
        assert!(h2_popup_walk(&r, &h2()).is_none());
        assert_eq!(h2_heal_cycle(&r, &h2()), Some(vec![24, 25, 26]));
        let inv = h2_inventory(&r, &h2()).unwrap();
        assert_eq!(h2_item_stock(&inv, 25), Some((1, 141)), "first index, total of both stacks");
        assert_eq!(h2_item_stock(&inv, 24), None);
    }

    /// ★★ 2026-10-21 비행서's own icon cell: the drawer block's table carries (28, 1) → display type 37 (strip cell 36),
    /// after the two orbs — and the block, three entries long, still fits its 0x100.
    #[test]
    fn the_item_icon_block_lists_the_flight_scroll_after_the_orbs() {
        let code = h2_item_icon_block(0x0016_388c).expect("the block encodes");
        assert!(code.len() <= ItemIconPatch::BLOCK_LEN as usize, "{} B of {:#x}", code.len(), ItemIconPatch::BLOCK_LEN);
        let mut table = Vec::new();
        for (ty, id, disp) in ItemIconPatch::CELLS {
            table.extend_from_slice(&[ty, id, disp]);
        }
        table.push(0);
        assert!(code.windows(table.len()).any(|w| w == table.as_slice()), "the (type, id, display) table, 0-terminated, is in the block");
        assert_eq!(ItemIconPatch::CELLS[2], (28, 1, 37), "비행서 = the 귀환서 type's id 1");
        assert!(
            ItemIconPatch::CELLS.iter().enumerate().all(|(i, &(_, _, d))| d == ItemIconPatch::SHIPPED_CELLS + 1 + i as u8),
            "display types are numbered after the shipped strip, in table order (= the asset's OWN_CELLS order)"
        );
    }

    /// ★★ 2026-10-17 엘릭서 on a plate (user: 「포션종류 취급」): its code is its display type — 35, the strip cell its own
    /// icon is in ([`ItemIconPatch`]) and past every shipped type — and the plate counts the (21, 7) records only: never
    /// the type's id-0 record (마력구 하급), never another orb.
    #[test]
    fn the_elixir_plate_counts_its_own_records() {
        let (mut m, _) = item_world(1);
        // [0] 포도주 ×87 → 엘릭서 ×3 · [2] 하이포션 ×42 → 망각의 구 (21, 3) ×5
        m.put(0x4990_3000 + 4 + Hero2Java::ITEM_TYPE_OFF, &[21]);
        m.put(0x4990_3000 + 4 + Hero2Java::ITEM_ID_OFF, &[7]);
        m.u32(0x4990_3000 + 4 + Hero2Java::ITEM_COUNT_OFF, 3);
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[21]);
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_ID_OFF, &[3]);
        m.u32(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_COUNT_OFF, 5);
        let inv = h2_inventory(&m.reader(), &h2()).unwrap();
        assert_eq!(h2_item_stock(&inv, H2_PLATE_ELIXIR), Some((0, 3)));
        assert_eq!(h2_item_stock(&inv, 21), None, "type 21's id-0 record is the 마력구 — not here");
        assert_eq!(h2_item_stock(&inv, 25), Some((1, 99)));
        let cycle = [24u8, 25, 26];
        assert_eq!(h2_plate_item_code(&cycle, 21, 7), Some(H2_PLATE_ELIXIR));
        assert_eq!(h2_plate_item_code(&cycle, 21, 3), None, "망각의 구");
        assert_eq!(h2_plate_item_code(&cycle, 21, 0), None, "마력구");
        assert_eq!(h2_plate_item_code(&cycle, 25, 0), Some(25));
        assert_eq!(h2_plate_item_code(&cycle, 28, 0), Some(28), "귀환서 (the drive)");
        assert_eq!(h2_plate_item_code(&cycle, 25, 1), None);
        assert_eq!((h2_plate_item_record(H2_PLATE_ELIXIR), h2_plate_item_record(24)), ((21, 7), (24, 0)));
        assert!(ItemIconPatch::CELLS.contains(&(21, 7, H2_PLATE_ELIXIR)), "the plate draws the elixir's own cell");
        assert!(H2_PLATE_ELIXIR > ItemIconPatch::SHIPPED_CELLS && H2_PLATE_ELIXIR < 64, "past the types, inside quickpage::ITEM_KIND_MAX");
        assert!(!h2_item_drive_kind(H2_PLATE_ELIXIR));
    }

    /// ★★ 2026-10-21 비행서 on a plate (user: 「비행서 아이템 퀵슬롯에 등록 되게」): its code is its display type 37 — the
    /// blue scroll cell — it counts the (28, 1) records only (never the 귀환서 (28, 0)), and it is a DRIVE kind.
    #[test]
    fn the_flight_scroll_plate_counts_its_own_records() {
        let (mut m, _) = item_world(1);
        // [0] 포도주 ×87 → 비행서 ×2 · [2] 하이포션 ×42 → 귀환서 ×5
        m.put(0x4990_3000 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        m.put(0x4990_3000 + 4 + Hero2Java::ITEM_ID_OFF, &[1]);
        m.u32(0x4990_3000 + 4 + Hero2Java::ITEM_COUNT_OFF, 2);
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        m.u32(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_COUNT_OFF, 5);
        let inv = h2_inventory(&m.reader(), &h2()).unwrap();
        assert_eq!(h2_item_stock(&inv, H2_PLATE_FLIGHT), Some((0, 2)));
        assert_eq!(h2_item_stock(&inv, 28), Some((2, 5)), "the 귀환서 plate still counts the id-0 records only");
        let cycle = [24u8, 25, 26];
        assert_eq!(h2_plate_item_code(&cycle, 28, 1), Some(H2_PLATE_FLIGHT));
        assert_eq!(h2_plate_item_code(&cycle, 28, 0), Some(28));
        assert_eq!(h2_plate_item_record(H2_PLATE_FLIGHT), (28, 1));
        assert!(ItemIconPatch::CELLS.contains(&(28, 1, H2_PLATE_FLIGHT)), "the plate draws the scroll's own blue cell");
        assert!(H2_PLATE_FLIGHT < 64, "inside quickpage::ITEM_KIND_MAX");
        assert!(h2_item_drive_kind(H2_PLATE_FLIGHT), "pressed through the bag popup, not `0`");
        assert!(!h2_item_bindable(&cycle, 28, 1), "never S7's — its rows come from the move-row planner");
    }

    /// ★★ 2026-10-20 상점주인의 혼 (user: 「영구 아이템 … 사용하면 상점npc에게 대화한것처럼」): `itm/21[8]` is the host's
    /// `H2Oblivion::Shop` — its popup row is the same host 사용하기 (gm 90) the elixir uses, its icon is the second appended
    /// strip cell, and its one gated write is the stock static. ★★ 2026-10-21 (user: 「상점주인의 혼 아이템도 퀵슬롯등록해서
    /// 사용가능」): its plate code is that display type 36 — it counts the (21, 8) records of the INVENTORY only, and it is
    /// pressed by the host (`AccountState::use_shop_plate`), neither `0` nor the item-use drive.
    #[test]
    fn the_shop_orb_is_the_hosts_portable_shop() {
        assert_eq!(h2_oblivion_of(21, 8), Some(H2Oblivion::Shop));
        assert_eq!(h2_oblivion_of(21, 7), Some(H2Oblivion::Elixir));
        assert_eq!(h2_oblivion_of(21, 9), None, "the next id is nobody's yet");
        assert_eq!(h2_oblivion_row_for(H2Oblivion::Shop), Hero2Java::GM_ROW_USE_SHOP);
        assert_eq!(Hero2Java::GM_ROW_USE_SHOP, Hero2Java::GM_ROW_USE_ELIXIR, "the same 사용하기 text row — the record tells them apart");
        let cycle = [24u8, 25, 26];
        assert_eq!(h2_plate_item_code(&cycle, 21, 8), Some(H2_PLATE_SHOP_ORB), "★ 2026-10-21 a plate, by its display type");
        assert_eq!(h2_plate_item_record(H2_PLATE_SHOP_ORB), (21, 8));
        assert_eq!(H2_PLATE_SHOP_ORB, H2_ICON_SHOP_ORB, "the plate draws the orb's own red cell");
        assert!(H2_PLATE_SHOP_ORB < 64, "inside quickpage::ITEM_KIND_MAX");
        assert!(!h2_item_drive_kind(H2_PLATE_SHOP_ORB), "pressed by the host's own shop, not the bag popup");
        assert!(!h2_item_bindable(&cycle, 21, 8), "never S7's — its rows come from the move-row planner");
        assert!([H2_PLATE_ELIXIR, H2_PLATE_FLIGHT].iter().all(|c| *c != H2_PLATE_SHOP_ORB), "three codes, three records");
        // The stock: the inventory's (21, 8) records only — an elixir (21, 7) beside it is not one.
        let (mut w, _) = item_world(1);
        w.put(0x4990_3000 + 4 + Hero2Java::ITEM_TYPE_OFF, &[21]);
        w.put(0x4990_3000 + 4 + Hero2Java::ITEM_ID_OFF, &[7]);
        w.u32(0x4990_3000 + 4 + Hero2Java::ITEM_COUNT_OFF, 4);
        let inv = h2_inventory(&w.reader(), &h2()).unwrap();
        assert_eq!(h2_item_stock(&inv, H2_PLATE_SHOP_ORB), None, "no orb in this inventory");
        w.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[21]);
        w.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_ID_OFF, &[8]);
        w.u32(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_COUNT_OFF, 1);
        let inv = h2_inventory(&w.reader(), &h2()).unwrap();
        assert_eq!(h2_item_stock(&inv, H2_PLATE_SHOP_ORB), Some((2, 1)));
        assert_eq!(h2_item_stock(&inv, H2_PLATE_ELIXIR), Some((0, 4)));
        assert!(ItemIconPatch::CELLS.contains(&(21, 8, H2_ICON_SHOP_ORB)), "the drawer shows its red orb");
        assert_eq!(H2_ICON_SHOP_ORB, H2_PLATE_ELIXIR + 1, "cell 35, right after the elixir's");
        let m = Mem::new();
        assert_eq!(h2_reset_gate(&m.reader(), &h2(), H2Oblivion::Shop, 0x1234), JavaWrite::ShopStock, "no character field is ever written for the shop");
        assert_eq!(Hero2Java::SHOP_EVENT, (4, 0));
    }

    /// ★★ 2026-10-17 the elixir's popup in the INVENTORY wants 퀵슬롯등록 · 퀵슬롯해제 after its 사용하기 and before the move
    /// row; in the warehouse — and on any other record — it does not. The two labels are relabelled once, only over the
    /// game's own `1번에 등록` / `3번에 등록`, and the bind rows are found by their handles.
    #[test]
    fn the_elixir_popup_wants_the_two_plate_rows_in_the_inventory() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        let gm = |i: u32| 0x4843_2000 + i * 0x10;
        let record = |kind: i8, id: i8| H2Item { handle: 0x4845_0300, kind, id, count: 3, d: 0, e: 0, f: 0, name: Vec::new() };
        let win = H2Win { handle: 0x4843_0100, fields: 0x4980_1000, class: 0x19_5300 };
        let popup = |bag: u32, rec: H2Item, labels: Vec<u32>| H2BagPopup {
            handle: 0x4843_0200,
            fields: 0x4985_0000,
            window: H2InvWin { win, bag, panel: (28, 51), on_top: false },
            menu_fields: 0x4980_0000,
            cell: 0,
            index: 0,
            record: rec,
            kind: 3,
            sel: 0,
            rows: labels.len() as i8,
            height: 0,
            labels_handle: 0x4844_0000,
            labels_fields: 0x4906_0000,
            labels_len: labels.len() as u32,
            labels,
        };
        let inv = 0x4845_0000u32;
        let account = [Some(0x4847_0000u32), Some(0x4847_0100)];
        let r = m.reader();
        let p = popup(inv, record(21, 7), vec![gm(31), gm(28)]);
        assert_eq!(
            h2_popup_wanted_rows(&r, &h2, &p, &account),
            vec![Hero2Java::GM_ROW_USE_ELIXIR, Hero2Java::GM_ROW_BIND, Hero2Java::GM_ROW_UNBIND, Hero2Java::GM_ROW_TO_ACCOUNT]
        );
        assert_eq!(h2_plate_bind_rows(&r, &h2, &p), (None, None), "not there yet");
        let half = popup(inv, record(21, 7), vec![gm(31), gm(28), gm(90), gm(34)]);
        assert_eq!(h2_plate_bind_rows(&r, &h2, &half), (Some(3), None), "등록 is on, 해제 a poll later");
        let p2 = popup(account[0].unwrap(), record(21, 7), vec![gm(31), gm(28)]);
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &p2, &account), vec![Hero2Java::GM_ROW_USE_ELIXIR, Hero2Java::GM_ROW_TO_BAG], "the warehouse: no plate rows");
        let p3 = popup(inv, record(21, 3), vec![gm(31), gm(28)]);
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &p3, &account), vec![Hero2Java::GM_ROW_RESET_STAT, Hero2Java::GM_ROW_TO_ACCOUNT], "망각의 구: as before");
        let p4 = popup(inv, record(6, 0), vec![gm(31), gm(28)]);
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &p4, &account), vec![Hero2Java::GM_ROW_TO_ACCOUNT]);
        // ★★ 2026-10-20 상점주인의 혼: 사용하기 in the inventory, the move row with it; in the warehouse the move row ONLY
        // (user: 「계정창고에 넣을 수 있어야해 … 계정창고에서 사용은 안되어야해」), and a warehouse popup never reads as its row.
        // (this world's gm table has 40 rows, so row 90's handle does not resolve here — `h2_oblivion_row`'s own
        //  inventory gate is exercised by the probe's `--h2-shop-orb` on the warehouse popup, which it refuses.)
        // ★★ 2026-10-21 (user: 「계정창고에 있는건 여전히 퀵슬롯등록되면 안돼고 … 인벤토리에 있을때만」): in the inventory
        // 퀵슬롯등록 · 퀵슬롯해제 after its 사용하기; in the warehouse still the move row alone.
        let shop = popup(inv, record(21, 8), vec![gm(31), gm(28)]);
        assert_eq!(
            h2_popup_wanted_rows(&r, &h2, &shop, &account),
            vec![Hero2Java::GM_ROW_USE_SHOP, Hero2Java::GM_ROW_BIND, Hero2Java::GM_ROW_UNBIND, Hero2Java::GM_ROW_TO_ACCOUNT]
        );
        assert_eq!(h2_popup_plate_code(&r, &h2, &shop), Some(H2_PLATE_SHOP_ORB));
        let shop_wh = popup(account[0].unwrap(), record(21, 8), vec![gm(31), gm(28)]);
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &shop_wh, &account), vec![Hero2Java::GM_ROW_TO_BAG], "the warehouse: no 사용하기, no plate rows for the shop orb");
        assert_eq!(h2_popup_plate_code(&r, &h2, &shop_wh), None, "never registered from the warehouse");
        let shop6 = popup(inv, record(21, 8), vec![gm(31), gm(28), gm(90), gm(34), gm(35), gm(78)]);
        assert_eq!(h2_plate_bind_rows(&r, &h2, &shop6), (Some(3), Some(4)));
        assert_eq!(h2_plate_bind_rows(&r, &h2, &popup(account[0].unwrap(), record(21, 8), shop6.labels.clone())), (None, None));
        // all six on: [상세보기 버리기 (사용하기) 등록 해제 (창고에넣기)] — the rows are found by handle
        let p5 = popup(inv, record(21, 7), vec![gm(31), gm(28), gm(90), gm(34), gm(35), gm(78)]);
        assert_eq!(h2_plate_bind_rows(&r, &h2, &p5), (Some(3), Some(4)));
        assert_eq!(h2_plate_bind_rows(&r, &h2, &popup(account[0].unwrap(), record(21, 7), p5.labels.clone())), (None, None));
        assert_eq!(h2_plate_bind_rows(&r, &h2, &popup(inv, record(21, 3), p5.labels.clone())), (None, None), "망각의 구");
        // ★★ 2026-10-21 비행서 (28, 1): stage 1 in the inventory = the game's [사용하기 상세보기 버리기] + 등록 · 해제 · 창고에넣기;
        // in the warehouse the move row only; 귀환서 (28, 0) is S7's (its plate rows come from the relabel, not this planner).
        let fl = popup(inv, record(28, 1), vec![gm(30), gm(31), gm(28)]);
        assert_eq!(h2_popup_plate_code(&r, &h2, &fl), Some(H2_PLATE_FLIGHT));
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &fl, &account), vec![Hero2Java::GM_ROW_BIND, Hero2Java::GM_ROW_UNBIND, Hero2Java::GM_ROW_TO_ACCOUNT]);
        let fl_wh = popup(account[0].unwrap(), record(28, 1), vec![gm(30), gm(31), gm(28)]);
        assert_eq!(h2_popup_wanted_rows(&r, &h2, &fl_wh, &account), vec![Hero2Java::GM_ROW_TO_BAG], "the warehouse: no plate rows");
        assert_eq!(h2_popup_plate_code(&r, &h2, &popup(inv, record(28, 0), vec![gm(30), gm(31), gm(28)])), None, "귀환서 is S7's");
        let fl6 = popup(inv, record(28, 1), vec![gm(30), gm(31), gm(28), gm(34), gm(35), gm(78)]);
        assert_eq!(h2_plate_bind_rows(&r, &h2, &fl6), (Some(3), Some(4)));
        assert_eq!(h2_plate_bind_rows(&r, &h2, &fl), (None, None), "not there yet");
        // the labels: the game's two → ours, once
        let writes = h2_register_label_writes(&r, [h2_gm_row_handle(&r, &h2, 34), h2_gm_row_handle(&r, &h2, 35)]).unwrap();
        assert_eq!(writes.iter().map(|(_, b)| b.clone()).collect::<Vec<_>>(), vec![H2_LABEL_BIND.to_vec(), H2_LABEL_UNBIND.to_vec()]);
        drop(r);
        for (a, b) in &writes {
            m.put(*a, b);
        }
        let r = m.reader();
        assert_eq!(h2_register_label_writes(&r, [h2_gm_row_handle(&r, &h2, 34), h2_gm_row_handle(&r, &h2, 35)]), Some(vec![]), "idempotent");
        assert_eq!(h2_register_label_writes(&r, [h2_gm_row_handle(&r, &h2, 31), h2_gm_row_handle(&r, &h2, 35)]), None, "not a register row: touch nothing");
    }

    /// ★★ 2026-10-17 엘릭서 × 술꾼의 장화: the host starts the walk the way unit F does for a potion — DRUNK_LEFT ← W_DRUNK —
    /// and only with the boots worn.
    #[test]
    fn an_elixir_starts_the_drunk_walk_only_with_the_boots_worn() {
        let mut m = Mem::new();
        let block = 0x4c00_0000u32;
        m.u32(block + GearPatch::W_DRUNK, 0);
        m.u32(block + GearPatch::DRUNK_LEFT, 0);
        assert_eq!(h2_gear_drink_write(&m.reader(), block), None, "no boots");
        m.u32(block + GearPatch::W_DRUNK, u32::from(GearPatch::DRUNK_FRAMES));
        m.u32(block + GearPatch::DRUNK_LEFT, 37);
        assert_eq!(h2_gear_drink_write(&m.reader(), block), Some((block + GearPatch::DRUNK_LEFT, 200u32.to_le_bytes().to_vec())), "a second one starts it over");
        assert_eq!(h2_gear_drink_write(&m.reader(), 0x4c10_0000), None, "unreadable");
    }

    #[test]
    fn the_item_relabel_grows_to_five_rows_in_the_painters_order_then_restores() {
        let (mut m, _) = item_world(1);
        let writes = {
            let r = m.reader();
            let p = h2_item_popup_walk(&r, &h2(), (0, 0)).unwrap();
            h2_item_popup_relabel_writes(&r, &p)
        };
        // 2 label bytes + 2 handles + length + rows + height + 3 repaint flags
        assert_eq!(writes.len(), 2 + 2 + 3 + 3, "{writes:x?}");
        assert_eq!(writes[0].1, H2_LABEL_BIND.to_vec());
        assert_eq!(writes[1].1, H2_LABEL_UNBIND.to_vec());
        assert_eq!(writes[2].0, 0x4906_0000 + 8 + 3 * 4, "handle slot 3 before the length");
        assert_eq!(writes[3].0, 0x4906_0000 + 8 + 4 * 4);
        assert_eq!(writes[4], (0x4906_0000 + 4, 5u32.to_le_bytes().to_vec()));
        assert_eq!(writes[5].1, vec![5u8]);
        assert_eq!(writes[6].1, 86u32.to_le_bytes().to_vec(), "6 + 16*5");
        for (a, b) in &writes {
            m.put(*a, b);
        }
        let r = m.reader();
        let p = h2_item_popup_walk(&r, &h2(), (0, 0)).unwrap();
        assert_eq!(p.shape(), Some(false), "ours");
        assert!(h2_item_popup_relabel_writes(&r, &p).is_empty(), "idempotent");
        assert!(h2_popup_walk(&r, &h2()).is_none(), "still not a skill popup");
        // The tap router sees five rows: the box is 86 tall, row 4 is the last.
        assert_eq!(h2_popup_box(&r, &h2(), 5).map(|b| b.3), None, "no screen statics in this world");
        // Restore from a cursor on our row: cursor first, then the three fields.
        let mut p2 = p.clone();
        p2.sel = 4;
        let restore = h2_item_popup_restore_writes(&p2);
        assert_eq!(restore[0], (p2.cursor_addr(), vec![0u8]));
        assert_eq!(restore[1], (0x4906_0000 + 4, 3u32.to_le_bytes().to_vec()));
        assert_eq!(restore.len(), 1 + 3 + 3);
        assert_eq!(h2_item_popup_restore_writes(&p).len(), 3 + 3, "cursor on a native row: no cursor write");
        // The heal-select producer: 하이포션 = ordinal 1 (already), index 1 (already) → nothing;
        // 포도주 = ordinal 2, index 0 → two bytes; 포션 = none in the bag → None.
        let (w, i, n) = h2_heal_select_writes(&r, &h2(), 25).unwrap();
        assert!(w.is_empty());
        assert_eq!((i, n), (1, 141));
        let (w, i, n) = h2_heal_select_writes(&r, &h2(), 26).unwrap();
        assert_eq!(w, vec![(0x4990_0000 + 4 + Hero2Java::INV_C_OFF, vec![2u8]), (0x4990_0000 + 4 + Hero2Java::INV_HEAL_OFF, vec![0u8])]);
        assert_eq!((i, n), (0, 87));
        assert!(h2_heal_select_writes(&r, &h2(), 24).is_none());
        assert!(h2_heal_select_writes(&r, &h2(), 27).is_none(), "not in the cycle");
    }

    /// A popup over a record that is NOT a cycle item (a second bag, a 치료제) is walked
    /// but not bindable; a popup whose labels are not the three gm rows has no shape.
    #[test]
    fn the_item_popup_refuses_what_it_does_not_know() {
        let (mut m, _) = item_world(0);
        {
            let r = m.reader();
            let p = h2_item_popup_walk(&r, &h2(), (0, 0)).unwrap();
            assert_eq!(p.item_kind, 26);
            assert!(p.bindable(&[24, 25, 26]));
        }
        // Third label swapped for another row: no shape, no writes.
        m.u32(0x4906_0000 + 8 + 2 * 4, 0x4843_2000 + 36 * 0x10);
        let r = m.reader();
        let p = h2_item_popup_walk(&r, &h2(), (0, 0)).unwrap();
        assert_eq!(p.shape(), None);
        assert!(h2_item_popup_relabel_writes(&r, &p).is_empty());
        assert!(h2_item_popup_restore_writes(&p).is_empty());
        drop(r);
        // The window shows another bag: not walked at all.
        m.u32(0x4980_1000 + 4 + Hero2Java::INV_WIN_BAG_OFF, 0x4845_0500);
        let r = m.reader();
        assert!(h2_item_popup_walk(&r, &h2(), (0, 0)).is_none());
    }

    // ── the item-use drive (2026-09-18, ⑧) ───────────────────────────────────────
    //
    // `item_world` is the END of the sequence (menu → bag → popup); these tests walk
    // the world through the screens the drive expects by editing the same fake heap,
    // one key at a time, and check what the drive asks for at each.

    /// The state word and the chain, as the drive will see them.
    fn set_screen(m: &mut Mem, field: bool, menu: bool, bag: bool, popup: Option<u8>) {
        let h2 = h2();
        let (addr, fv, wv) = match GuestBuild::Hero2Ktf.app_state() {
            Some(AppState::Absolute { addr, field, window, .. }) => (addr, field, window),
            _ => unreachable!(),
        };
        m.u32(addr, if field { fv } else { wv });
        m.u32(h2.menu_slot, if menu { 0x4843_0000 } else { 0 });
        m.put(0x4980_0000 + 4 + Hero2Java::WIN_ROWS_OFF, &[Hero2Java::MENU_ROWS]);
        m.u32(0x4980_0000 + 4 + Hero2Java::WIN_CHILD_OFF, if bag { 0x4843_0100 } else { 0 });
        m.put(0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, &[28]);
        m.u32(0x4980_1000 + 4 + Hero2Java::WIN_CHILD_OFF, if popup.is_some() { 0x4843_0200 } else { 0 });
        if let Some(k) = popup {
            m.put(0x4985_0000 + 4 + Hero2Java::POPUP_KIND_OFF, &[k]);
        }
    }

    fn cursor_writes(writes: &[(u32, Vec<u8>)]) -> Vec<(u32, Vec<u8>)> {
        writes.iter().filter(|(_, b)| b.len() == 1).cloned().collect()
    }

    #[test]
    fn the_drive_uses_a_recovery_item_through_the_bags_own_popup() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        // Not on the field: refused before any key.
        assert_eq!(h2_use_start(&m.reader(), &h2, 26).err(), Some("not on the field with the menu closed"));
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_start(&m.reader(), &h2, 24).err(), Some("none of that item in the bag"), "no 포션 in this bag");
        let mut d = h2_use_start(&m.reader(), &h2, 26).expect("포도주 x87 is there");
        // 1. field → CLR
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, key, .. } => {
                assert!(writes.is_empty());
                assert_eq!(key, H2Key::Clr);
            }
            a => panic!("{a:?}"),
        }
        assert_eq!(d.step, H2UseStep::OpenInventory);
        // The game has not opened the menu yet: nothing more goes out.
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        // 2. menu up → INVENTORY row + OK
        set_screen(&mut m, false, true, false, None);
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, key, .. } => {
                assert_eq!(cursor_writes(&writes), vec![(0x4980_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![1u8])]);
                assert_eq!(writes.len(), 1 + 1, "cursor + one repaint flag (the menu)");
                assert_eq!(key, H2Key::Ok);
            }
            a => panic!("{a:?}"),
        }
        // 3. bag up → the record's index (포도주 = [0]) + OK
        set_screen(&mut m, false, true, true, None);
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, key, .. } => {
                assert_eq!(cursor_writes(&writes), vec![(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![0u8])]);
                assert_eq!(writes.len(), 1 + 2, "cursor + two repaint flags");
                assert_eq!(key, H2Key::Ok);
            }
            a => panic!("{a:?}"),
        }
        assert_eq!(d.index, Some(0));
        // 4. the popup (kind 6, cursor already on 사용하기) → OK, nothing written
        set_screen(&mut m, false, true, true, Some(6));
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, key, what } => {
                assert!(writes.is_empty(), "{what}: {writes:x?}");
                assert_eq!(key, H2Key::Ok);
            }
            a => panic!("{a:?}"),
        }
        assert_eq!(d.step, H2UseStep::CloseInventory, "a recovery item is used on that OK — no question follows");
        // 5. popup gone, bag still up → CLR
        set_screen(&mut m, false, true, true, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        // 6. only the menu → CLR
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait, "the menu is still there for a frame");
        // 7. the field
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done);
    }

    /// ★★ 2026-10-21 비행서 plate: the drive walks to the scroll's kind-7 popup, sends NO 사용하기 (the game's would be the
    /// 귀환서's) and asks for the town list instead; the list is the player's for as long as it is up — no clock — and the
    /// two ways out are the warp (the field back, nothing open) and CLR (the bag left, closed by the drive).
    #[test]
    fn the_drive_stops_at_the_flight_scroll_for_the_town_list() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        // Record [2] = 비행서 ×42 (was 하이포션).
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_ID_OFF, &[1]);
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_start(&m.reader(), &h2, 28).err(), Some("none of that item in the bag"), "the 귀환서 plate does not take a 비행서");
        let mut d = h2_use_start(&m.reader(), &h2, H2_PLATE_FLIGHT).unwrap();
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Ok, .. }));
        set_screen(&mut m, false, true, true, None);
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, .. } => assert_eq!(cursor_writes(&writes)[0].1, vec![2u8], "record [2]"),
            a => panic!("{a:?}"),
        }
        m.put(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[2]);
        // The scroll's popup is kind 7 (its type is the 귀환서's): no key — the town list, and the screen goes over.
        set_screen(&mut m, false, true, true, Some(7));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::FlightPicker { popup: 0x4843_0200 });
        assert_eq!(d.step, H2UseStep::Handoff);
        // The town list (the same kind-7 popup, the host's labels): the player's, no clock.
        let polls = d.polls;
        for _ in 0..500 {
            assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        }
        assert_eq!(d.polls, polls);
        // CLR: the list goes, the bag stays → the drive closes the rest.
        set_screen(&mut m, false, true, true, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Resume);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done);
        // A town instead: the host closes the menu and sets the field state (then warps) — the drive is simply done.
        let mut d = h2_use_start(&m.reader(), &h2, H2_PLATE_FLIGHT).unwrap();
        d.step = H2UseStep::Handoff;
        set_screen(&mut m, false, true, true, Some(7));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done);
    }

    #[test]
    fn the_drive_hands_the_return_scrolls_question_to_the_player() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        // Put a 귀환서 x12 in record [2] (was 하이포션 x42).
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        assert!(h2_item_bindable(&[24, 25, 26], 28, 0), "귀환서 goes on a plate");
        assert!(h2_item_bindable(&[24, 25, 26], 27, 0), "치료제 too");
        assert!(!h2_item_bindable(&[24, 25, 26], 27, 1), "…but only its id-0 record");
        assert!(!h2_item_bindable(&[24, 25, 26], 29, 0));
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 28).unwrap();
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Ok, .. }));
        set_screen(&mut m, false, true, true, None);
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, .. } => assert_eq!(cursor_writes(&writes)[0].1, vec![2u8], "record [2]"),
            a => panic!("{a:?}"),
        }
        // The popup over 귀환서 is kind 7 (a kind-6 one here would be somebody else's).
        m.put(0x4980_1000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[2]);
        set_screen(&mut m, false, true, true, Some(7));
        m.put(0x4985_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, &[1]);
        match h2_use_step(&m.reader(), &h2, &mut d) {
            H2UseAction::Act { writes, key, .. } => {
                assert_eq!(cursor_writes(&writes), vec![(0x4985_0000 + 4 + Hero2Java::WIN_CURSOR_OFF, vec![0u8])], "the popup's cursor was not on 사용하기");
                assert_eq!(key, H2Key::Ok);
            }
            a => panic!("{a:?}"),
        }
        assert_eq!(d.step, H2UseStep::AwaitConfirm);
        // The old popup is still there for a frame: wait. Then the question: hand off.
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        set_screen(&mut m, false, true, true, Some(11));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Handoff { why: "the game asks 귀환하시겠습니까" });
        // The player thinks; the drive's clock does not run.
        let polls = d.polls;
        for _ in 0..500 {
            assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        }
        assert_eq!(d.polls, polls);
        // 아니오: the box goes, the bag stays → the drive resumes and closes.
        set_screen(&mut m, false, true, true, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Resume);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done);

        // 예 instead: the game closes everything itself and warps — a black frame or two
        // with no window and no field, then the field.
        let (mut m, _) = item_world(0);
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 28).unwrap();
        d.step = H2UseStep::Handoff;
        set_screen(&mut m, false, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait, "between maps");
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done);
    }

    /// The handoff is the drive's only clockless state, so every way OUT of it has to be
    /// one it recognises. Two the sequence does not produce but a thumb does: the question
    /// answered with CLR (the game drops back to the record's own popup — ours to close),
    /// and a screen that never comes back (a death, a return to the title) — which must
    /// not leave the drive alive for the rest of the session, refusing every later press.
    #[test]
    fn the_drive_always_gets_out_of_the_handoff() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        m.put(0x4990_3000 + 2 * 0x100 + 4 + Hero2Java::ITEM_TYPE_OFF, &[28]);
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 28).unwrap();
        d.step = H2UseStep::Handoff;
        // CLR on the question: back to the 귀환서 popup (kind 7). Take the screen and unwind.
        set_screen(&mut m, false, true, true, Some(7));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Resume);
        assert_eq!(d.step, H2UseStep::Unwind);
        for shape in [(false, true, true, Some(7)), (false, true, true, None), (false, true, false, None)] {
            set_screen(&mut m, shape.0, shape.1, shape.2, shape.3);
            assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }), "{shape:?}");
        }
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Done, "an unwind nobody failed ends as done");

        // A screen that never comes back: the one handoff wait that is the game's time,
        // not the player's, and therefore the one with a clock.
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 28).unwrap();
        d.step = H2UseStep::Handoff;
        set_screen(&mut m, false, false, false, None);
        let mut last = H2UseAction::Wait;
        for _ in 0..=H2_USE_HANDOFF_POLLS {
            last = h2_use_step(&m.reader(), &h2, &mut d);
        }
        assert_eq!(last, H2UseAction::Abort { why: "the screen never came back from the box" });
    }

    /// A message box where the bag should be closing (치료제 with nothing to cure is the
    /// shape this is here for) is the player's to read: hand off, then finish the close.
    #[test]
    fn a_message_of_the_games_own_is_handed_over_not_waited_out() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 26).unwrap();
        d.step = H2UseStep::CloseInventory;
        set_screen(&mut m, false, true, true, Some(6));
        m.object(0x4843_0200, 0x4985_0000, 0x19_5400, h2.classes.message_window);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Handoff { why: "the game answered with a message" });
        for _ in 0..200 {
            assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait, "no clock while it is up");
        }
        set_screen(&mut m, false, true, true, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Resume);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
    }

    /// A screen the drive did not expect makes it back out with CLR — one per screen —
    /// and report the reason; a game that stops answering ends it on the clock.
    #[test]
    fn the_drive_backs_out_of_what_it_does_not_expect() {
        let (mut m, _) = item_world(0);
        let h2 = h2();
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 26).unwrap();
        let _ = h2_use_step(&m.reader(), &h2, &mut d);
        set_screen(&mut m, false, true, false, None);
        let _ = h2_use_step(&m.reader(), &h2, &mut d);
        set_screen(&mut m, false, true, true, None);
        let _ = h2_use_step(&m.reader(), &h2, &mut d);
        // A kind-3 popup where the item's menu should be.
        set_screen(&mut m, false, true, true, Some(3));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait);
        assert_eq!(d.step, H2UseStep::Unwind);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Wait, "one CLR per screen: the chain has not shrunk");
        set_screen(&mut m, false, true, true, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, false, true, false, None);
        assert!(matches!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Act { key: H2Key::Clr, .. }));
        set_screen(&mut m, true, false, false, None);
        assert_eq!(h2_use_step(&m.reader(), &h2, &mut d), H2UseAction::Abort { why: "the popup is not the item's 사용하기 menu" });

        // The clock: a menu that never opens.
        set_screen(&mut m, true, false, false, None);
        let mut d = h2_use_start(&m.reader(), &h2, 26).unwrap();
        let _ = h2_use_step(&m.reader(), &h2, &mut d);
        let mut last = H2UseAction::Wait;
        for _ in 0..=H2_USE_STEP_POLLS {
            last = h2_use_step(&m.reader(), &h2, &mut d);
        }
        assert_eq!(last, H2UseAction::Abort { why: "the game did not answer a key" });
    }

    // ── inventory paging (#13 step 4) ────────────────────────────────────────────

    /// The `bl` encoder against the SHIPPED bytes of all seven sites (client.bin1120,
    /// read with dump_hero2_java.py's coordinates on 2026-09-21) and the retargeted form.
    #[test]
    fn the_bl_encoder_reproduces_the_shipped_sites() {
        let patch = GuestBuild::Hero2Ktf.inventory_page_patch().unwrap();
        let shipped: [(u32, [u8; 4], [u8; 4]); 7] = [
            (0x146688, [0x22, 0xf0, 0x78, 0xfd], [0x22, 0xf0, 0x6a, 0xfd]),
            (0x146984, [0x22, 0xf0, 0xfa, 0xfb], [0x22, 0xf0, 0xec, 0xfb]),
            (0x1469dc, [0x22, 0xf0, 0xce, 0xfb], [0x22, 0xf0, 0xc0, 0xfb]),
            (0x146a5e, [0x22, 0xf0, 0x8d, 0xfb], [0x22, 0xf0, 0x7f, 0xfb]),
            (0x146a9e, [0x22, 0xf0, 0x6d, 0xfb], [0x22, 0xf0, 0x5f, 0xfb]),
            (0x146dfe, [0x22, 0xf0, 0xbd, 0xf9], [0x22, 0xf0, 0xaf, 0xf9]),
            (0x146f10, [0x22, 0xf0, 0x34, 0xf9], [0x22, 0xf0, 0x26, 0xf9]),
        ];
        for (i, (bl, virt, direct)) in shipped.iter().enumerate() {
            assert_eq!(patch.sites[i].bl, *bl);
            assert_eq!(h2_thumb_bl(*bl, patch.helper_virtual), *virt, "site {bl:#x} shipped");
            assert_eq!(h2_thumb_bl(*bl, patch.helper_direct), *direct, "site {bl:#x} retargeted");
        }
    }

    /// The trampoline's three literals sit where its three `ldr r0, [pc, #…]` reach
    /// (Thumb: `(pc & !3) + 4 + imm`), and the jump keeps the Thumb bit.
    #[test]
    fn the_trampoline_literals_are_where_its_loads_look() {
        let block = 0x4844_1000;
        let t = h2_page_trampoline(block, 1, 0x0013_6d3c);
        let hw = |i: usize| u16::from_le_bytes([t[i], t[i + 1]]);
        let word = |i: usize| u32::from_le_bytes([t[i], t[i + 1], t[i + 2], t[i + 3]]);
        // ldr r0, [pc, #imm] = 0x4800 | imm/4; its address = ((at + 4) & !3) + imm.
        let literal_of = |at: usize| ((at + 4) & !3) + ((hw(at) & 0xff) as usize) * 4;
        assert_eq!(hw(0) & 0xff00, 0x4800);
        assert_eq!(literal_of(0), 20, "&ctx.bag");
        assert_eq!(word(20), block + InventoryPagePatch::CTX_BAG);
        assert_eq!(hw(8) & 0xff00, 0x4800);
        assert_eq!(literal_of(8), 24, "&ctx.off");
        assert_eq!(word(24), block + InventoryPagePatch::CTX_OFF);
        assert_eq!(hw(14) & 0xff00, 0x4800);
        assert_eq!(literal_of(14), 28, "body");
        assert_eq!(word(28), 0x0013_6d3d, "Thumb bit set on the body");
        // bne +14: 0xd1 | ((14 - (6 + 4)) / 2) = 0xd102, landing on the body load.
        assert_eq!(hw(6), 0xd102);
        assert_eq!(hw(16), 0x4700, "bx r0");
        // The block layout: defs and trampolines never overlap and fit the block.
        for i in 0..3u8 {
            assert!(InventoryPagePatch::def_at(block, i) + InventoryPagePatch::DEF_LEN <= block + InventoryPagePatch::TRAMPS);
            assert!(InventoryPagePatch::tramp_at(block, i) + InventoryPagePatch::TRAMP_LEN <= block + InventoryPagePatch::BLOCK_LEN);
        }
    }

    /// The install plan refuses an image whose sites do not read the shipped `bl` or
    /// whose runtime defs do not name the expected bodies, and otherwise writes the block,
    /// then the cells, then the branches — never a branch before its cell.
    #[test]
    fn the_install_plan_verifies_first_and_orders_block_cells_branches() {
        let patch = GuestBuild::Hero2Ktf.inventory_page_patch().unwrap();
        let block = 0x4845_2000u32;
        let mut m = Mem::new();
        for site in &patch.sites {
            m.put(site.bl, &h2_thumb_bl(site.bl, patch.helper_virtual));
            m.u32(site.cell, 0x0318_043f);
        }
        for target in &patch.targets {
            let mut def = vec![0u8; InventoryPagePatch::DEF_LEN as usize];
            def[0..4].copy_from_slice(&(target.body | 1).to_le_bytes());
            def[4..8].copy_from_slice(&0x0019_2844u32.to_le_bytes());
            m.put(target.def, &def);
        }
        let writes = h2_page_install_writes(&m.reader(), &patch, block).expect("a clean image installs");
        // Block first: ctx, then per target a def copy (word 0 = tramp|1) + the trampoline.
        assert_eq!(writes[0].0, block + InventoryPagePatch::CTX_BAG);
        assert_eq!(writes[1].0, block + InventoryPagePatch::CTX_OFF);
        for i in 0..3u8 {
            let (a, d) = &writes[2 + i as usize * 2];
            assert_eq!(*a, InventoryPagePatch::def_at(block, i));
            assert_eq!(u32::from_le_bytes([d[0], d[1], d[2], d[3]]), InventoryPagePatch::tramp_at(block, i) | 1);
            assert_eq!(&d[4..8], &0x0019_2844u32.to_le_bytes(), "the rest of the def is the runtime's own");
            assert_eq!(writes[3 + i as usize * 2].0, InventoryPagePatch::tramp_at(block, i));
        }
        let cells = &writes[8..15];
        let bls = &writes[15..22];
        for (site, (a, d)) in patch.sites.iter().zip(cells) {
            assert_eq!(*a, site.cell);
            assert_eq!(d, &InventoryPagePatch::def_at(block, site.target).to_le_bytes().to_vec());
        }
        for (site, (a, d)) in patch.sites.iter().zip(bls) {
            assert_eq!(*a, site.bl);
            assert_eq!(d, &h2_thumb_bl(site.bl, patch.helper_direct).to_vec());
        }
        assert_eq!(writes.len(), 22);
        // Apply, and the plan reads as installed; a second plan is identical (idempotent).
        for (a, d) in &writes {
            m.put(*a, d);
        }
        assert!(h2_page_installed(&m.reader(), &patch, block));
        assert_eq!(h2_page_install_writes(&m.reader(), &patch, block).unwrap(), writes);
        // A foreign byte at one site refuses the WHOLE plan.
        m.put(patch.sites[3].bl, &[0, 0, 0, 0]);
        assert!(h2_page_install_writes(&m.reader(), &patch, block).is_none());
        assert!(!h2_page_installed(&m.reader(), &patch, block));
        // An unaligned or null block is refused before anything is read.
        assert!(h2_page_install_writes(&m.reader(), &patch, 0).is_none());
        assert!(h2_page_install_writes(&m.reader(), &patch, block + 2).is_none());
    }

    /// ★★ 2026-10-20 the 사용하기 → `a.g(B)V` site: the shipped `bl` (client.bin1120 @0x146b54 = `22 f0 12 fb`, virtual
    /// helper), a plan ordered copy → trampoline → cell → `bl`, idempotent, and refused on a foreign site, cell or def.
    #[test]
    fn the_use_site_plan_matches_the_image_and_orders_block_cell_branch() {
        let p = GuestBuild::Hero2Ktf.item_use_page_patch().unwrap();
        assert_eq!(h2_thumb_bl(p.bl, p.helper_virtual), [0x22, 0xf0, 0x12, 0xfb], "the shipped call to the virtual helper");
        let (page_block, block) = (0x4845_2000u32, 0x4845_3000u32);
        let mut m = Mem::new();
        m.put(p.bl, &h2_thumb_bl(p.bl, p.helper_virtual));
        m.u32(p.cell, 0x0319_075f); //           the shipped, unresolved reference (odd)
        let mut def = vec![0u8; InventoryPagePatch::DEF_LEN as usize];
        def[0..4].copy_from_slice(&(p.body | 1).to_le_bytes());
        def[4..8].copy_from_slice(&0x0019_2a00u32.to_le_bytes());
        m.put(p.def, &def);
        let writes = h2_use_page_install_writes(&m.reader(), &p, page_block, block).expect("a clean image installs");
        assert_eq!(writes.len(), 4);
        assert_eq!(writes[0].0, block + ItemUsePagePatch::DEF_AT);
        assert_eq!(&writes[0].1[0..4], &((block + ItemUsePagePatch::CODE_AT) | 1).to_le_bytes(), "word 0 → the trampoline");
        assert_eq!(&writes[0].1[4..8], &0x0019_2a00u32.to_le_bytes(), "the rest of the def is the runtime's own");
        assert_eq!(writes[1].0, block + ItemUsePagePatch::CODE_AT);
        assert!(ItemUsePagePatch::CODE_AT as usize + writes[1].1.len() <= ItemUsePagePatch::BLOCK_LEN as usize);
        assert_eq!(writes[2], (p.cell, (block + ItemUsePagePatch::DEF_AT).to_le_bytes().to_vec()));
        assert_eq!(writes[3], (p.bl, h2_thumb_bl(p.bl, p.helper_direct).to_vec()), "the arming branch last");
        for (a, d) in &writes {
            m.put(*a, d);
        }
        assert!(h2_use_page_installed(&m.reader(), &p, block));
        assert_eq!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).unwrap(), writes, "idempotent");
        // A wrapper chained at the def (GearPatch's 술꾼의 장화) is still a Thumb pointer: accepted.
        m.u32(p.def, 0x4b00_0101);
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).is_some());
        // Refusals: a foreign cell, a def word 0 that is not code, a foreign site, a bad block.
        m.u32(p.def, p.body | 1);
        m.u32(p.cell, 0x4b00_0200);
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).is_none(), "a cell naming someone else");
        m.u32(p.cell, p.def);
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).is_some(), "a resolved cell = the runtime def");
        m.u32(p.def, 0x4b00_0200);
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).is_none(), "a def word 0 that is not code");
        m.u32(p.def, p.body | 1);
        m.put(p.bl, &[0, 0, 0, 0]);
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block).is_none());
        assert!(!h2_use_page_installed(&m.reader(), &p, block));
        m.put(p.bl, &h2_thumb_bl(p.bl, p.helper_virtual));
        assert!(h2_use_page_install_writes(&m.reader(), &p, 0, block).is_none(), "no paging block");
        assert!(h2_use_page_install_writes(&m.reader(), &p, page_block, block + 2).is_none());
    }

    /// LEFT on cell 0 / RIGHT on a page's last cell cross pages, cyclically; every other arrow
    /// press is the game's own. ★ 2026-10-02: the fifth page's last cell is 14.
    #[test]
    fn the_arrow_rule_crosses_pages_only_at_the_grids_two_ends() {
        assert_eq!(h2_page_arrow(0, 0, true), Some((4, 14)), "LEFT on the first cell of page 1 wraps to page 5's last cell — 14 of its 15");
        assert_eq!(h2_page_arrow(2, 0, true), Some((1, 27)));
        assert_eq!(h2_page_arrow(4, 0, true), Some((3, 27)));
        assert_eq!(h2_page_arrow(4, 14, false), Some((0, 0)), "RIGHT on the last cell of page 5 wraps to page 1");
        assert_eq!(h2_page_arrow(4, 27, false), Some((0, 0)), "a cursor past the cells still leaves by the edge");
        assert_eq!(h2_page_arrow(3, 27, false), Some((4, 0)));
        assert_eq!(h2_page_arrow(1, 27, false), Some((2, 0)));
        for c in 1..27i8 {
            assert_eq!(h2_page_arrow(1, c, true), None);
            assert_eq!(h2_page_arrow(1, c, false), None);
        }
        for c in 1..14i8 {
            assert_eq!(h2_page_arrow(4, c, false), None, "inside the fifth page RIGHT is the game's own");
        }
        assert_eq!(h2_page_arrow(1, 27, true), None, "LEFT on 27 is the game's own move to 26");
        assert_eq!(h2_page_arrow(1, 0, false), None, "RIGHT on 0 is the game's own move to 1");
    }

    /// ★ 2026-10-09: the alchemist's chain (state 8, rooted at `aw.a`) — `aw` → `aj` → the picker `k` over a list of
    /// `n` bag indices. Returns the list's handle.
    fn alchemist_picker(m: &mut Mem, n: usize) -> (u32, u32, Vec<u8>) {
        m.u32(state_slot(), Hero2Java::NPC_WINDOW_STATE);
        let (aw, aw_f, aw_c) = (0x4810_0000u32, 0x4810_0100u32, 0x4810_0200u32);
        let (aj, aj_f, aj_c) = (0x4811_0000u32, 0x4811_0100u32, 0x4811_0200u32);
        let (k, k_f, k_c) = (0x4812_0000u32, 0x4812_0100u32, 0x4812_0200u32);
        let (list, list_f) = (0x4813_0000u32, 0x4813_0100u32);
        m.u32(Hero2Java::ALCHEMIST_SLOT, aw);
        m.object(aw, aw_f, aw_c, Hero2Java::ALCHEMIST_CLASS_DESC);
        m.object(aj, aj_f, aj_c, 0x0019_23a0);
        m.object(k, k_f, k_c, Hero2Java::PICKER_CLASS_DESC);
        m.u32(aw_f + 4 + Hero2Java::WIN_CHILD_OFF, aj);
        m.u32(aj_f + 4 + Hero2Java::WIN_CHILD_OFF, k);
        m.u32(k_f + 4 + Hero2Java::WIN_CHILD_OFF, 0);
        let full: Vec<u8> = (0..n as u8).map(|i| 126 - i).collect();
        m.bytes(list, list_f, &full);
        m.u32(k_f + 4 + Hero2Java::PICKER_LIST_OFF, list);
        m.u32(Hero2Java::ALCHEMIST_ORIGIN.0, 30);
        m.u32(Hero2Java::ALCHEMIST_ORIGIN.1, 40);
        (k, list, full)
    }

    /// ★ 2026-10-09 (user: *"재료가방창도 127칸으로 … 신규아이템 조합서들을 구성할꺼야"*): a picker over more than 28
    /// entries is found in the alchemist's chain, paged 28 at a time by rewriting its list in place — that page's
    /// indices, the length word, the cursor inside the page — and its arrows cross at the grid's two ends.
    #[test]
    fn a_long_picker_list_is_paged_in_place() {
        let h2 = h2();
        let mut m = Mem::new();
        let (k, list, full) = alchemist_picker(&mut m, 40);
        let v = h2_picker_window(&m.reader(), &h2).expect("the picker in the alchemist's chain");
        assert_eq!((v.win.handle, v.list, v.len, v.panel, v.on_top, v.cover), (k, list, 40, (30, 40), true, None));
        assert_eq!(v.chain.len(), 3, "aw → aj → k");
        assert_eq!([h2_picker_pages(0), h2_picker_pages(28), h2_picker_pages(29), h2_picker_pages(92), h2_picker_pages(127)], [1, 1, 2, 4, 5]);
        assert_eq!(h2_picker_page(&full, 1), &full[28..40]);
        assert!(h2_picker_page(&full, 2).is_empty());
        let w = h2_picker_page_writes(&v, &full, 1, 20).expect("page 2");
        assert_eq!(w[0], (JavaWrite::PickerList, v.base, full[28..40].to_vec()), "that page's indices over the array's first bytes");
        assert_eq!(w[1], (JavaWrite::PickerList, v.base - 4, 12u32.to_le_bytes().to_vec()), "then the length word");
        assert_eq!(w[2], (JavaWrite::WidgetCursor, v.win.fields + 4 + Hero2Java::WIN_CURSOR_OFF, vec![11]), "the cursor inside the page");
        assert_eq!(w.len(), 3 + 3, "and the chain's three repaint flags");
        assert!(h2_picker_page_writes(&v, &full, 2, 0).is_none(), "no page past the list");
        assert!(h2_picker_page_writes(&v, &full[..20], 0, 0).is_none(), "a list the array no longer fits is refused");
        // Arrows: the picker's own pages, cyclic; the last page's last entry is where LEFT lands.
        assert_eq!(h2_picker_arrow(&full, 0, 27, false), Some((1, 0)));
        assert_eq!(h2_picker_arrow(&full, 1, 27, false), Some((0, 0)), "RIGHT on cell 27 of the last page wraps (the game's own j.i is 28)");
        assert_eq!(h2_picker_arrow(&full, 1, 0, true), Some((0, 27)));
        assert_eq!(h2_picker_arrow(&full, 0, 0, true), Some((1, 11)), "LEFT on page 1's first cell = page 2's last entry");
        assert_eq!(h2_picker_arrow(&full, 0, 13, true), None);
        assert_eq!(h2_picker_arrow(&full[..28], 0, 27, false), None, "one page: every arrow is the game's");
        // Not in state 8 (or no alchemist) → no chain; a chain without a picker → none.
        m.u32(state_slot(), 3);
        assert!(h2_picker_window(&m.reader(), &h2).is_none());
        m.u32(state_slot(), Hero2Java::NPC_WINDOW_STATE);
        m.u32(0x4811_0100 + 4 + Hero2Java::WIN_CHILD_OFF, 0);
        assert!(h2_picker_window(&m.reader(), &h2).is_none(), "aj without its picker");
        m.object(0x4810_0000, 0x4810_0100, 0x4810_0200, 0x0019_2c58);
        assert!(h2_picker_chain(&m.reader(), &h2).is_none(), "a root that is not the alchemist's is refused");
    }

    /// ★ 2026-10-09: a CELL patch accepts both shipped states (the odd index, the resolved definition), counts a patched
    /// one as done, and refuses the whole list on a foreign word.
    #[test]
    fn cell_redirects_accept_both_shipped_states_and_refuse_a_foreign_one() {
        let cells = GuestBuild::Hero2Ktf.craft_worn_skip();
        assert_eq!(cells.len(), 2);
        let mut m = Mem::new();
        m.u32(cells[0].0, cells[0].1);
        m.u32(cells[1].0, cells[1].2);
        let (todo, already, total) = h2_cell_redirect_writes(&m.reader(), cells);
        assert_eq!((todo.len(), already, total), (2, 0, 2));
        assert!(todo.iter().all(|(_, w)| u32::from_le_bytes(*w) == 0x0018_9410), "bq.b(BB)B's definition");
        for (a, w) in &todo {
            m.put(*a, w);
        }
        assert_eq!(h2_cell_redirect_writes(&m.reader(), cells), (Vec::new(), 2, 2), "patched: confirmed without a write");
        m.u32(cells[1].0, 0x1234_5679);
        assert_eq!(h2_cell_redirect_writes(&m.reader(), cells), (Vec::new(), 0, 2), "a foreign word refuses all");
        // The two definitions are bq's own, side by side in its vtable (35 · 36) and a whole number of records in.
        for (_, _, resolved, patched) in cells {
            assert_eq!(((resolved - 0x0018_5644) % 0x1c, (patched - 0x0018_5644) % 0x1c), (0, 0));
            assert_eq!(patched - resolved, 0x1c, "bq.a(BB)B and bq.b(BB)B are neighbours in the definition table");
        }
        assert!(GuestBuild::Ktf.craft_worn_skip().is_empty() && GuestBuild::Ktf.craft_material_mark().is_empty() && GuestBuild::Ktf.picker_grid_shift().is_empty());
    }

    /// ★ 2026-10-02 (user: *"마지막 5번쨰가방에서 칸 몇개를 지워야해"*): 127 = 4 × 28 + 15 — the fifth page is 15
    /// cells, its window's `j.i` says so, and the 13 the painter draws past them are listed for the UI.
    #[test]
    fn the_fifth_page_has_the_fifteen_cells_that_are_left() {
        assert_eq!((0..5).map(h2_page_cells).collect::<Vec<_>>(), vec![28, 28, 28, 28, 15]);
        assert_eq!((0..5).map(|p| u32::from(h2_page_cells(p))).sum::<u32>(), Hero2Java::BAG_CAPACITY as u32, "every slot of the bag on a page, none more");
        assert_eq!(h2_page_cells(5), 0);
        let win = H2Win { handle: 0x4843_0100, fields: 0x4980_1000, class: 0x19_2c58 };
        let view = H2InvWin { win, bag: 0x4843_0700, panel: (28, 51), on_top: true };
        assert_eq!(h2_page_cells_write(&view, 4), (0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, vec![15]));
        assert_eq!(h2_page_cells_write(&view, 0), (0x4980_1000 + 4 + Hero2Java::WIN_ROWS_OFF, vec![28]), "back to q.<init>'s 28");
        // The select writes carry the count before a cursor inside it.
        let none = |_: u32, _: usize| Vec::new();
        let h2 = h2();
        let w = h2_page_select_writes(&none, &h2, 0x4b85_af00, &view, 4, 27);
        let at = |addr: u32| w.iter().position(|(a, _)| *a == addr);
        let (count, cursor) = (at(view.win.fields + 4 + Hero2Java::WIN_ROWS_OFF).unwrap(), at(view.win.fields + 4 + Hero2Java::WIN_CURSOR_OFF).unwrap());
        assert!(count < cursor);
        assert_eq!((w[count].1.clone(), w[cursor].1.clone()), (vec![15], vec![14]), "cursor 27 asked on page 5 is cell 14");
        assert_eq!(h2_page_select_writes(&none, &h2, 0x4b85_af00, &view, 0, 27)[3].1, vec![27]);
        // The cells past 15, where `q.a(II)V` fills them — the grid moved 7 right or not.
        let hidden = h2_page_hidden_cells((28, 51), 15, Hero2Java::INV_GRID_SHIFT);
        assert_eq!(hidden.len(), 13);
        assert_eq!((hidden[0], hidden[5], hidden[6]), ((57, 112, 14, 14), (132, 112, 14, 14), (42, 127, 14, 14)), "row 2 from col 1, then all of row 3");
        assert_eq!(h2_page_hidden_cells((28, 51), 15, 0)[0].0, 50, "unshifted");
        assert!(h2_page_hidden_cells((28, 51), 28, 7).is_empty());
    }

    /// ★ 2026-10-02: on the 15-cell page UP/DOWN keep the column where the game's 7 × 4 wrap would not (DOWN from
    /// 8..=13 → its 0, UP from 1..=6 → its clamp to 14); everywhere else, and on full pages, the move is the game's.
    #[test]
    fn up_and_down_keep_the_column_on_the_short_page() {
        for c in 8..=13i8 {
            assert_eq!(h2_page_vertical(4, c, false), Some((c - 7) as u8), "DOWN from row 2 wraps to the top of its column");
        }
        assert_eq!(h2_page_vertical(4, 14, false), Some(0), "the lone cell of row 3 wraps to the top");
        for c in 1..=6i8 {
            assert_eq!(h2_page_vertical(4, c, true), Some((c + 7) as u8), "UP from the top goes to the column's lowest cell");
        }
        assert_eq!(h2_page_vertical(4, 0, true), Some(14), "column 0 reaches row 3");
        for c in 0..=7i8 {
            assert_eq!(h2_page_vertical(4, c, false), None, "DOWN onto a cell is the game's own");
        }
        for c in 7..=14i8 {
            assert_eq!(h2_page_vertical(4, c, true), None, "UP onto a cell is the game's own");
        }
        assert_eq!(h2_page_vertical(4, 20, true), None, "a cursor past the cells is not this rule's");
        for p in 0..4u8 {
            for c in 0..28i8 {
                assert_eq!((h2_page_vertical(p, c, true), h2_page_vertical(p, c, false)), (None, None), "a full page is the game's");
            }
        }
    }

