    /// ★ 2026-10-02: the cooldown tick counter, run as the guest runs it — one per call of
    /// `ag.i()V`, then on to its body with `r1` and the caller untouched.
    #[test]
    fn the_cooldown_clock_counts_a_tick_and_runs_the_body() {
        let p = GuestBuild::Hero2Ktf.cooldown_clock_patch().expect("hero2 has the cooldown clock");
        assert_eq!((p.def, p.body), (0x0018_6118, 0x0011_20a8));
        assert_eq!(p.def, 0x0018_5644 + 99 * 0x1c, "ag.i()V's definition record");
        let mut cpu = Cpu::new();
        cpu.load(BLOCK, &h2_cd_clock_block(&p));
        for n in 1..=3u32 {
            cpu.r[1] = 0x4848_0000;
            cpu.r[14] = EXIT | 1;
            let body = p.body;
            let end = cpu.run(BLOCK, BLOCK, BLOCK + CooldownClockPatch::BLOCK_LEN, &mut |_, pc| {
                assert_eq!(pc, body, "the block leaves only for the body");
                Step::Stop
            });
            assert_eq!(end, p.body, "on to the body (Thumb)");
            assert_eq!((cpu.r[1], cpu.r[14]), (0x4848_0000, EXIT | 1), "r1 and the caller untouched");
            assert_eq!(cpu.rd32(BLOCK + CooldownClockPatch::COUNT), n);
        }
        // The count wraps like the host's subtraction does.
        cpu.wr32(BLOCK + CooldownClockPatch::COUNT, u32::MAX);
        cpu.r[14] = EXIT | 1;
        cpu.run(BLOCK, BLOCK, BLOCK + CooldownClockPatch::BLOCK_LEN, &mut |_, _| Step::Stop);
        let read = |a: u32, l: usize| (0..l as u32).map(|i| cpu.rd8(a + i)).collect::<Vec<u8>>();
        assert_eq!(h2_cd_clock_read(&read, BLOCK), Some(0));
    }

