    // ── ★ 2026-10-12: 인장 상급 — the two rewritten stretches of the alchemist, RUN ───────────

    /// `x.c()V` 0x14b6d0.. as patched (`r0` = the seal's id, `[sp+8]` = `this`): on to 0x14b71c with `r5` = min,
    /// `r2` = max − 4 (0x14b722 takes it, 0x14b754 adds 4) and `r3` = `this` — the shipped numbers for 0..2, 15..20 from 3.
    #[test]
    fn the_seal_rewrite_rolls_fifteen_to_twenty_from_the_top_tier() {
        let sites = GuestBuild::Hero2Ktf.seal_top_tier();
        assert_eq!([0, 1, 2, 3, 4].map(GuestBuild::seal_range), [(0, 4), (2, 7), (5, 10), (15, 20), (15, 20)]);
        for id in 0u32..=5 {
            let mut cpu = Cpu::new();
            for (at, _, patched) in sites.iter().filter(|s| (0x0014_b6d0..0x0014_b6e6).contains(&s.0)) {
                cpu.load(*at, &patched.to_le_bytes());
            }
            cpu.wr32(cpu.r[13] + 8, 0x4848_1234);
            cpu.r[0] = id;
            cpu.r[14] = EXIT | 1;
            let end = cpu.run(0x0014_b6d0, 0x0014_b6d0, 0x0014_b6e6, &mut |_, _| Step::Stop);
            let (lo, hi) = GuestBuild::seal_range(id as u8);
            assert_eq!(end, 0x0014_b71c, "id {id}: on to the shipped x.a:Lbu; read");
            assert_eq!((cpu.r[5], cpu.r[2] + 4, cpu.r[3]), (u32::from(lo), u32::from(hi), 0x4848_1234), "id {id}");
        }
    }

    /// `x.b()V` 0x14aed4.. (the shipped `cmp r0,#1 · beq` first, then the patched four): id 2 → 10,000, id ≥ 3 → 20,000,
    /// both on to the shared store at 0x14aee6 with `r0` = the cost's cell literal and `r1` = `this`; id 1 and id ≤ 0 to
    /// their shipped cases (0x14aefc · 0x14aeee).
    #[test]
    fn the_seal_cost_doubles_for_the_top_tier() {
        let sites = GuestBuild::Hero2Ktf.seal_top_tier();
        for id in [-1i32, 0, 1, 2, 3, 4] {
            let mut cpu = Cpu::new();
            cpu.load(0x0014_aed4, &0x2801u16.to_le_bytes()); //  cmp r0,#1
            cpu.load(0x0014_aed6, &0xd011u16.to_le_bytes()); //  beq 0x14aefc
            cpu.load(0x0014_aedc, &0x2802u16.to_le_bytes()); //  cmp r0,#2 (kept)
            cpu.load(0x0014_aee2, &0x4811u16.to_le_bytes()); //  ldr r0,[pc,#0x44] (the cost's cell literal)
            cpu.load(0x0014_aee4, &0x1c21u16.to_le_bytes()); //  adds r1,r4,#0
            for (at, _, patched) in sites.iter().filter(|s| (0x0014_aed8..0x0014_aee2).contains(&s.0)) {
                cpu.load(*at, &patched.to_le_bytes());
            }
            cpu.wr32(0x0014_af24, 0x2710);
            cpu.wr32(0x0014_af28, 0xfffe_8100);
            cpu.r[0] = id as u32;
            cpu.r[4] = 0x4848_5678;
            cpu.r[14] = EXIT | 1;
            let end = cpu.run(0x0014_aed4, 0x0014_aed4, 0x0014_aee6, &mut |_, _| Step::Stop);
            match id {
                1 => assert_eq!(end, 0x0014_aefc, "id 1: its shipped 5,000"),
                i if i <= 0 => assert_eq!(end, 0x0014_aeee, "id {i}: its shipped 1,000 (or none)"),
                _ => {
                    assert_eq!(end, 0x0014_aee6, "id {id}: the shared store");
                    let want = if id >= i32::from(GuestBuild::SEAL_TOP_ID) { GuestBuild::SEAL_TOP_COST } else { 10_000 };
                    assert_eq!((cpu.r[2], cpu.r[0], cpu.r[1]), (want, 0xfffe_8100, 0x4848_5678), "id {id}");
                }
            }
        }
    }

    // ── ★ 2026-10-12: the slot-screen focus ───────────────────────────────────────────────

    /// The block run as the guest runs it: the shipped finder first (it puts the cursor on the first save), then the
    /// cursor ← LAST only when LAST is a row of this screen (`< j.i`) and `ag.a(B)Z(LAST)` says it holds a save — asked
    /// through the finder's own cell and the static helper, and only then. r4 · r5 · the stack as they were.
    #[test]
    fn the_slot_screen_opens_on_the_last_slot_when_it_holds_a_save() {
        let p = GuestBuild::Hero2Ktf.slot_focus_patch().expect("hero2 has the slot focus");
        assert_eq!((p.def - 0x0018_5644) % 0x1c, 0, "be.a()V's definition record is a row of the table");
        let saves = [false, true, true, false, true];
        for rows in [3u32, 5] {
            for last in [None, Some(0u8), Some(1), Some(2), Some(3), Some(4), Some(7)] {
                let mut cpu = Cpu::new();
                cpu.load(BLOCK, &h2_slot_focus_block(&p, BLOCK, h2_slot_focus_last(last)).expect("encodes"));
                let (win, fb) = cpu.object(0x40, 0x2222);
                cpu.wr32(fb + u32::from(SlotFocusPatch::CURSOR_OFF), 0);
                cpu.wr32(fb + u32::from(SlotFocusPatch::ROWS_OFF), rows);
                cpu.r[1] = win;
                cpu.r[4] = 0x4444;
                cpu.r[5] = 0x5555;
                cpu.r[14] = EXIT | 1;
                let (mut finder, mut asked) = (0, Vec::new());
                let first = saves.iter().position(|s| *s).unwrap() as u32;
                let end = cpu.run(BLOCK, BLOCK, BLOCK + SlotFocusPatch::BLOCK_LEN, &mut |c, pc| {
                    if pc == p.body {
                        assert_eq!(c.r[1], win, "the finder gets the screen");
                        finder += 1;
                        c.wr32(fb + u32::from(SlotFocusPatch::CURSOR_OFF), first);
                        return Step::Return;
                    }
                    if pc == p.call_static {
                        assert_eq!(c.r[0], p.cell_has_save, "the finder's own cell");
                        asked.push(c.r[1]);
                        c.r[0] = u32::from(saves[c.r[1] as usize]);
                        return Step::Return;
                    }
                    Step::Stop
                });
                let case = format!("rows {rows} last {last:?}");
                assert_eq!(end, EXIT, "{case}: returns to be.<init>");
                assert_eq!(finder, 1, "{case}: the shipped finder runs once, first");
                let in_screen = last.filter(|s| u32::from(*s) < rows);
                assert_eq!(asked, in_screen.map(u32::from).into_iter().collect::<Vec<_>>(), "{case}: asked only for a row of the screen");
                let want = match in_screen {
                    Some(s) if saves[usize::from(s)] => u32::from(s),
                    _ => first,
                };
                assert_eq!(cpu.rd32(fb + u32::from(SlotFocusPatch::CURSOR_OFF)), want, "{case}");
                assert_eq!((cpu.r[4], cpu.r[5], cpu.r[13]), (0x4444, 0x5555, STACK_TOP), "{case}: r4 · r5 · the stack");
            }
        }
    }

