                cpu.field(fb, p.blessing_off, u32::from(blessed));
                cpu.r[1] = me;
                cpu.r[2] = kind;
                for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                    cpu.r[i] = v;
                }
                let at = cpu.run(BLOCK + CombatPatch::SEQ_MAP_AT, BLOCK, END, &mut |_, _| Step::Stop);
