    /// ★ 2026-10-03: EVERY wave is drawn as the crescent — the body's own drawer `n.a(BBBII)V`
    /// through the static helper, with sequence 21 (22 while the owner is under 신의가호; 24 for
    /// a wave carrying 발도's mark as its attack), the wave's frame as a byte, the wave's own
    /// direction as the list (as the shipped painter passed it) and the paint origin stacked;
    /// the shipped painter is never entered. No owner: the blue crescent.
    #[test]
    fn the_wave_painter_draws_the_ring_blue_or_red_by_the_owners_blessing() {
        let p = patch();
        let mark = (-(i32::from(CombatPatch::IAIDO_WAVE_MARK))) as u32;
        for (dir, frame, blessed, owned, attack) in [
            (1u32, 0u32, false, true, 345u32),
            (4, 2, true, true, 345),
            (5, 1, false, true, 0),
            (8, 0, true, true, 1),
            (3, 4, true, false, 345),
            (2, 0xff, false, true, 345),
            (4, 3, true, true, mark),
            (1, 0, false, true, mark),
            (2, 1, true, false, mark),
            // ★★ 2026-10-17 a marked wave draws its own sequence: the radius-4/5 crescents · 천공의검's
            (3, 2, true, true, (-i32::from(CombatPatch::IAIDO_REACH_WAVE_SEQ)) as u32),
            (2, 4, true, true, (-i32::from(CombatPatch::IAIDO_REACH_WAVE_SEQ + 1)) as u32),
            (1, 1, false, false, (-i32::from(CombatPatch::SKY_WAVE_MARK)) as u32),
        ] {
            let mut cpu = installed();
            let (knight, kfb) = cpu.object(0x200, 0x2222);
            cpu.field(kfb, p.facing_off, 3);
            cpu.field(kfb, p.blessing_off, u32::from(blessed));
            let (wave, wfb) = cpu.object(0x80, 0x3333);
            cpu.field(wfb, p.wave_dir_off, dir);
            cpu.field(wfb, p.wave_owner_off, if owned { knight } else { 0 });
            cpu.field(wfb, p.wave_frame_off, frame);
            cpu.field(wfb, p.wave_attack_off, attack);
            cpu.r[1] = wave;
            cpu.r[2] = 111;
            cpu.r[3] = 222;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let mut drawn = Vec::new();
            let at = cpu.run(BLOCK + CombatPatch::WAVE_PAINT_AT, BLOCK, END, &mut |c, pc| {
                if pc == p.static_call {
                    let sp = c.r[13];
                    drawn.push((c.r[0], c.r[1], c.r[2], c.r[3], c.rd32(sp), c.rd32(sp + 4)));
                    return Step::Return;
                }
                assert_ne!(pc, p.wave_paint.1, "the shipped painter is never entered");
                Step::Stop
            });
            assert_eq!(at, EXIT, "dir {dir}: returns after drawing");
            let seq = if (attack as i32) < 0 {
                (-(attack as i32)) as u8
            } else if blessed && owned {
                CombatPatch::BLESSED_WAVE_RING_SEQ
            } else {
                CombatPatch::WAVE_RING_SEQ
            };
            let byte = frame as u8 as i8 as i32 as u32;
            assert_eq!(drawn, [(p.cell_draw_seq, u32::from(seq), byte, dir, 111, 222)], "dir {dir} blessed {blessed} owned {owned} attack {attack}");
            assert_eq!(cpu.rd32(wfb + 4 + p.wave_dir_off), dir, "the wave's direction untouched");
            assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
        }
    }

    /// ★ 2026-10-03: the wave constructor — the shipped body once, as passed, then the wave's
    /// lifetime ← 3 tiles, 5 while the knight is under 신의가호 (a null knight: 3). No second wave,
    /// no `new`, nothing handed to the stage. ★★ 2026-10-15 2차 E4: the gear's [`GearPatch::RANGE_LOBE`] bit flies it 5 too
    /// (the other bits, no gear word: 3; a null knight: 3 whatever the gear).
    #[test]
    fn the_wave_constructor_runs_the_body_and_sets_the_lifetime_by_the_blessing() {
        let p = patch();
        for (blessed, knighted, gear, want) in [
            (false, true, None, 3u32),
            (true, true, None, 5),
            (true, false, None, 3),
            (false, true, Some(GearPatch::RANGE_LOBE), 5),
            (false, true, Some(GearPatch::RANGE_STAR | GearPatch::RANGE_DAGGER3), 3),
            (false, true, Some(0), 3),
            (false, false, Some(GearPatch::RANGE_LOBE), 3),
        ] {
            let mut cpu = installed();
            if let Some(bits) = gear {
                gear_range(&mut cpu, bits);
            }
            let (knight, kfb) = cpu.object(0x200, 0x2222);
            cpu.field(kfb, p.blessing_off, u32::from(blessed));
            let (wave, wfb) = cpu.object(0x80, 0x3333);
            cpu.field(wfb, p.wave_life_off, 0x55); // what the body would leave (5 after sword_wave_range)
            cpu.r[1] = wave;
            cpu.r[2] = if knighted { knight } else { 0 };
            cpu.r[3] = 345;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let mut built = 0;
            let at = cpu.run(BLOCK + CombatPatch::WAVE_CTOR_AT, BLOCK, END, &mut |c, pc| {
                if pc == p.wave_ctor.1 {
                    assert_eq!((c.r[1], c.r[2], c.r[3]), (wave, if knighted { knight } else { 0 }, 345), "(wave, knight, attack) as passed");
                    built += 1;
                    return Step::Return;
                }
                assert!(pc != p.new_instance && pc != p.dispatch, "no second wave");
                Step::Stop
            });
            assert_eq!((at, built), (EXIT, 1), "blessed {blessed} knighted {knighted} gear {gear:?}");
            assert_eq!(cpu.rd32(wfb + 4 + p.wave_life_off), want, "blessed {blessed} knighted {knighted} gear {gear:?}: tiles to fly");
            assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
        }
        assert_eq!((CombatPatch::WAVE_LIFE, CombatPatch::BLESSED_WAVE_LIFE), (3, 5), "as far as the lobe reaches");
    }

    /// A knight whose action chain `a.o[a.i]` reads `kind`, standing at frame `frame`.
    fn caster(cpu: &mut Cpu, p: &CombatPatch, kind: i8, frame: u32, chain_ok: bool) -> u32 {
        caster_blessed(cpu, p, kind, frame, chain_ok, false)
    }

    fn caster_blessed(cpu: &mut Cpu, p: &CombatPatch, kind: i8, frame: u32, chain_ok: bool, blessed: bool) -> u32 {
        let (knight, kfb) = cpu.object(0x200, 0x2222);
        cpu.field(kfb, p.action_frame_off, frame);
        cpu.field(kfb, p.blessing_off, u32::from(blessed));
        if chain_ok {
            let chain = cpu.bytes(&[1, 2, kind as u8, 0xff, 0, 0, 0, 0]);
            cpu.field(kfb, p.combo_table_off, chain);
            cpu.field(kfb, p.combo_index_off, 2);
        }
        knight
    }

    /// ★★ 2026-10-03: the cast wrapper, RUN. 발도 at its hit frame sweeps through the game's own
    /// cell, plays sound 7 when something was hit and returns 1 (0 when nothing was); every other
    /// frame returns 1 without the body. 검기 at its spawn frame sweeps, then goes on to the body
    /// with `this` and the caller intact; every other frame, every other kind, an unreadable or
    /// out-of-range chain: straight to the body.
    #[test]
    fn the_cast_wrapper_sweeps_for_iaido_and_the_wave_and_passes_the_rest() {
        let p = patch();
        let (iaido, wave) = (i32::from(CombatPatch::IAIDO), i32::from(CombatPatch::WAVE));
        // (kind, frame, chain readable, sweep hits) → (sweeps, sounds, where it ends, r0 if it returned)
        let cases: [(i8, u32, bool, bool, u32, u32, bool, Option<u32>); 11] = [
            (iaido as i8, u32::from(CombatPatch::IAIDO_HIT_FRAME), true, true, 1, 1, false, Some(1)),
            (iaido as i8, u32::from(CombatPatch::IAIDO_HIT_FRAME), true, false, 1, 0, false, Some(0)),
            (iaido as i8, 0, true, true, 0, 0, false, Some(1)),
            (iaido as i8, 5, true, true, 0, 0, false, Some(1)),
            (wave as i8, u32::from(CombatPatch::WAVE_HIT_FRAME), true, true, 1, 0, true, None),
            (wave as i8, u32::from(CombatPatch::WAVE_HIT_FRAME), true, false, 1, 0, true, None),
            (wave as i8, 4, true, true, 0, 0, true, None),
            (5, 4, true, true, 0, 0, true, None),
            (-1, 3, true, true, 0, 0, true, None),
            (iaido as i8, u32::from(CombatPatch::IAIDO_HIT_FRAME), false, true, 0, 0, true, None),
            (0, 2, true, true, 0, 0, true, None),
        ];
        for (kind, frame, chain_ok, hits, want_sweeps, want_sounds, to_body, ret) in cases {
            let mut cpu = installed();
            let knight = caster(&mut cpu, &p, kind, frame, chain_ok);
            cpu.r[1] = knight;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let (mut sweeps, mut sounds) = (Vec::new(), Vec::new());
            let at = cpu.run(BLOCK + CombatPatch::CAST_AT, BLOCK, END, &mut |c, pc| {
                if pc == p.dispatch {
                    assert_eq!((c.r[0], c.r[1]), (p.cell_sweep, knight), "this.bx.h(B)Z through the game's cell");
                    sweeps.push(c.r[2]);
                    c.r[0] = u32::from(hits);
                    return Step::Return;
                }
                if pc == p.static_call {
                    assert_eq!(c.r[0], p.cell_sound, "br.a(B)V through case 4's cell");
                    sounds.push(c.r[1]);
                    return Step::Return;
                }
                assert!(pc != p.new_instance && pc != p.wave_ctor.1, "no wave without 신의가호");
                Step::Stop
            });
            let tag = format!("kind {kind} frame {frame} chain {chain_ok} hits {hits}");
            assert_eq!(sweeps.len(), want_sweeps as usize, "{tag}: sweeps");
            assert!(sweeps.iter().all(|k| *k == kind as u8 as u32), "{tag}: swept as its own kind");
            assert_eq!(sounds, vec![u32::from(CombatPatch::IAIDO_SOUND); want_sounds as usize], "{tag}: sounds");
            if to_body {
                assert_eq!(at, p.cast.1, "{tag}: on to the body");
                assert_eq!((cpu.r[1], cpu.r[14]), (knight, EXIT | 1), "{tag}: this and the caller intact");
            } else {
                assert_eq!(at, EXIT, "{tag}: returns");
                assert_eq!(Some(cpu.r[0]), ret, "{tag}: the return");
            }
            assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
        }
    }

    /// The quickbar `ag.j` (four values) and the four slots' counters `ag.a` at their statics — what 쌍월's window reads.
    /// Returns the counters' element block (the ints from +8).
    fn twin_bar(cpu: &mut Cpu, p: &CombatPatch, values: [u8; 4], counters: [i32; 4]) -> u32 {
        let bar = cpu.bytes(&values);
        cpu.wr32(p.quickbar_slot, bar);
        let cds = cpu.words(&counters.map(|c| c as u32));
        cpu.wr32(p.cooldown_slot, cds);
        cpu.rd32(cds)
    }

    /// The gear block's W_RANGE word with all of `bits` (the reach items sit past a byte).
    fn gear_range_word(cpu: &mut Cpu, bits: u32) {
        let w = cpu.alloc(4);
        cpu.wr32(w, bits);
        cpu.wr32(BLOCK + CombatPatch::GEAR_RANGE_PTR, w);
    }

    /// ★★ 2026-10-17 쌍월 reworked (user: *"발도 사용시 0.5초내로 재사용하면 쿨타임 없이 재사용가능하고, 재사용 한뒤에 기존 발도
    /// 쿨타임이 적용"*): 발도's LAST frame with [`GearPatch::IAIDO_TWICE`] frees the slot holding 발도 — its running counter
    /// saved, set to −1 (ready), the window open TWIN_UPDATES; no bit / no gear block / the re-cast / a window already open /
    /// a counter not running / 발도 on no slot: nothing. Never a sweep, the answer 1, `g.w` untouched (the 10-15 replay is gone).
    #[test]
    fn twin_moon_frees_iaido_for_a_window_at_its_last_frame() {
        let p = patch();
        let iaido = CombatPatch::IAIDO as i8;
        let last = u32::from(CombatPatch::IAIDO_FRAMES - 1);
        let twice = u32::from(GearPatch::IAIDO_TWICE);
        let v = CombatPatch::IAIDO_VALUE;
        // (W_RANGE, recast, left, the bar, the counters) → opens?
        for (bits, recast, left, bar, cds, opens) in [
            (Some(twice), 0u32, 0u32, [3u8, v, 1, 0xff], [10i32, 130, -1, -1], true),
            (Some(twice | u32::from(GearPatch::RANGE_STAR) | 2 << GearPatch::IAIDO_REACH_SHIFT), 0, 0, [v, 3, 1, 2], [125, 9, -1, 4], true),
            (Some(u32::from(GearPatch::RANGE_STAR)), 0, 0, [3, v, 1, 0xff], [10, 130, -1, -1], false),
            (None, 0, 0, [3, v, 1, 0xff], [10, 130, -1, -1], false),
            (Some(twice), 1, 0, [3, v, 1, 0xff], [10, 130, -1, -1], false),
            (Some(twice), 0, 4, [3, v, 1, 0xff], [10, 130, -1, -1], false),
            (Some(twice), 0, 0, [3, v, 1, 0xff], [10, -1, -1, -1], false),
            (Some(twice), 0, 0, [3, v, 1, 0xff], [10, 0, -1, -1], false),
            (Some(twice), 0, 0, [3, 4, 1, 0xff], [10, 130, -1, -1], false),
        ] {
            let mut cpu = installed();
            if let Some(b) = bits {
                gear_range_word(&mut cpu, b);
            }
            let cdb = twin_bar(&mut cpu, &p, bar, cds);
            cpu.wr32(BLOCK + CombatPatch::TWIN_RECAST, recast);
            cpu.wr32(BLOCK + CombatPatch::TWIN_LEFT, left);
            let knight = caster(&mut cpu, &p, iaido, last, true);
            let kfb = cpu.rd32(knight);
            cpu.r[1] = knight;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let at = cpu.run(BLOCK + CombatPatch::CAST_AT, BLOCK, END, &mut |_c, pc| {
                assert_ne!(pc, p.dispatch, "no sweep at the last frame");
                Step::Stop
            });
            let tag = format!("bits {bits:?} recast {recast} left {left} bar {bar:?} cds {cds:?}");
            assert_eq!((at, cpu.r[0]), (EXIT, 1), "{tag}");
            assert_eq!(cpu.rd32(kfb + 4 + p.action_frame_off), last, "{tag}: g.w untouched");
            let slot = bar.iter().position(|b| *b == v).unwrap_or(0);
            let counters: Vec<i32> = (0..4).map(|i| cpu.rd32(cdb + 8 + 4 * i as u32) as i32).collect();
            if opens {
                let mut want = cds.to_vec();
                want[slot] = -1;
                assert_eq!(counters, want, "{tag}: the slot ready");
                assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_SAVED) as i32, cds[slot], "{tag}: saved");
                assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_SLOT), slot as u32, "{tag}: the slot");
                assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_LEFT), u32::from(CombatPatch::TWIN_UPDATES), "{tag}: open");
            } else {
                assert_eq!(counters, cds.to_vec(), "{tag}: counters untouched");
                assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_LEFT), left, "{tag}: the window as it was");
            }
            assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
        }
    }

    /// ★★ 2026-10-17 쌍월: 발도's frame 0 (a cast) shuts the window — the cast is the re-cast exactly when it was open
    /// (TWIN_RECAST), so its own end opens none; frames 1, 2 and 4 leave both words. Always the answer 1, no sweep.
    #[test]
    fn twin_moon_marks_the_recast_at_frame_zero() {
        let p = patch();
        let iaido = CombatPatch::IAIDO as i8;
        for (frame, left, recast, want_left, want_recast) in
            [(0u32, 7u32, 0u32, 0u32, 1u32), (0, 0, 1, 0, 0), (0, 1, 0, 0, 1), (1, 7, 0, 7, 0), (2, 0, 1, 0, 1), (4, 5, 1, 5, 1)]
        {
            let mut cpu = installed();
            gear_range_word(&mut cpu, u32::from(GearPatch::IAIDO_TWICE));
            cpu.wr32(BLOCK + CombatPatch::TWIN_LEFT, left);
            cpu.wr32(BLOCK + CombatPatch::TWIN_RECAST, recast);
            let knight = caster(&mut cpu, &p, iaido, frame, true);
            cpu.r[1] = knight;
            let at = cpu.run(BLOCK + CombatPatch::CAST_AT, BLOCK, END, &mut |_c, pc| {
                assert_ne!(pc, p.dispatch, "no sweep");
                Step::Stop
            });
            let tag = format!("frame {frame} left {left} recast {recast}");
            assert_eq!((at, cpu.r[0]), (EXIT, 1), "{tag}");
            assert_eq!((cpu.rd32(BLOCK + CombatPatch::TWIN_LEFT), cpu.rd32(BLOCK + CombatPatch::TWIN_RECAST)), (want_left, want_recast), "{tag}");
        }
    }

    /// ★★ 2026-10-17 쌍월's window on the character update `a.g()V` (the UPDATE piece): an open window counts one down each
    /// update and always goes on to the body with `this` and the caller intact; the update that shuts it puts the freed slot's
    /// counter back — `SAVED − TWIN_UPDATES` (−1 when that is not positive) — only while that slot still holds 발도 and reads −1
    /// (a re-cast restarted it, another skill took the slot: left alone).
    #[test]
    fn twin_moon_window_runs_out_and_the_cooldown_comes_back() {
        let p = patch();
        let v = CombatPatch::IAIDO_VALUE;
        let w = i32::from(CombatPatch::TWIN_UPDATES);
        // (left, saved, slot, the bar, the counters) → (left after, the counters after)
        for (left, saved, slot, bar, cds, want_left, want) in [
            (0u32, 130i32, 1u32, [3u8, v, 1, 0xff], [10i32, -1, -1, -1], 0u32, [10i32, -1, -1, -1]),
            (5, 130, 1, [3, v, 1, 0xff], [10, -1, -1, -1], 4, [10, -1, -1, -1]),
            (1, 130, 1, [3, v, 1, 0xff], [10, -1, -1, -1], 0, [10, 130 - w, -1, -1]),
            (1, 130, 1, [3, v, 1, 0xff], [10, 140, -1, -1], 0, [10, 140, -1, -1]),
            (1, 130, 1, [3, 4, 1, 0xff], [10, -1, -1, -1], 0, [10, -1, -1, -1]),
            (1, 6, 0, [v, 3, 1, 0xff], [-1, 9, -1, -1], 0, [-1, 9, -1, -1]),
            (1, 40, 3, [3, 4, 1, v], [10, 9, -1, -1], 0, [10, 9, -1, 40 - w]),
        ] {
            let mut cpu = installed();
            let cdb = twin_bar(&mut cpu, &p, bar, cds);
            cpu.wr32(BLOCK + CombatPatch::TWIN_LEFT, left);
            cpu.wr32(BLOCK + CombatPatch::TWIN_SAVED, saved as u32);
            cpu.wr32(BLOCK + CombatPatch::TWIN_SLOT, slot);
            cpu.wr32(p.state_slot, 3); //                the field
            let (me, _) = cpu.object(0x200, 0x2222); //  a.j = 0: no hit-stop
            cpu.r[1] = me;
            cpu.r[3] = 0x3333;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let at = cpu.run(BLOCK + CombatPatch::UPDATE_AT, BLOCK, END, &mut |_c, _pc| Step::Stop);
            let tag = format!("left {left} saved {saved} slot {slot} bar {bar:?} cds {cds:?}");
            assert_eq!(at, p.update.1, "{tag}: on to the update's body");
            assert_eq!((cpu.r[1], cpu.r[3], cpu.r[14]), (me, 0x3333, EXIT | 1), "{tag}: this, r3 and the caller intact");
            assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_LEFT), want_left, "{tag}");
            let counters: Vec<i32> = (0..4).map(|i| cpu.rd32(cdb + 8 + 4 * i as u32) as i32).collect();
            assert_eq!(counters, want.to_vec(), "{tag}: the counters");
            assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
        }
        // a stagger (the hit-stop counter running) or not the field: the window holds — the game's tick does not run either
        for (hitstop, state) in [(3u32, 3u32), (1, 3), (0, 5), (0, 4)] {
            let mut cpu = installed();
            let cdb = twin_bar(&mut cpu, &p, [3, v, 1, 0xff], [10, -1, -1, -1]);
            cpu.wr32(BLOCK + CombatPatch::TWIN_LEFT, 1);
            cpu.wr32(BLOCK + CombatPatch::TWIN_SAVED, 130);
            cpu.wr32(BLOCK + CombatPatch::TWIN_SLOT, 1);
            cpu.wr32(p.state_slot, state);
            let (me, mfb) = cpu.object(0x200, 0x2222);
            cpu.field(mfb, p.hitstop_off, hitstop);
            cpu.r[1] = me;
            let at = cpu.run(BLOCK + CombatPatch::UPDATE_AT, BLOCK, END, &mut |_c, _pc| Step::Stop);
            assert_eq!((at, cpu.r[1]), (p.update.1, me), "hit-stop {hitstop} state {state}: the body all the same");
            assert_eq!(cpu.rd32(BLOCK + CombatPatch::TWIN_LEFT), 1, "hit-stop {hitstop} state {state}: the window holds");
            assert_eq!(cpu.rd32(cdb + 8 + 4) as i32, -1, "hit-stop {hitstop} state {state}: still ready");
        }
    }

    /// ★★ 2026-10-17 발도 특화 아이템 — the hit frame writes THIS cast's tiles, exactly [`CombatPatch::iaido_tiles`] with the
    /// radius 3 + the reach items (two at most — a third counts as two) and, under 신의가호, the band `R − 2` wide in the facing;
    /// then the one sweep (`bx.h(B)Z(9)`, the knight); under 신의가호 the crescent's mark is the radius's sequence (24 · 56 · 57).
    #[test]
    fn iaido_writes_its_tiles_by_the_reach_and_the_blessing() {
        let p = patch();
        let iaido = CombatPatch::IAIDO as i8;
        for items in 0..=3u32 {
            for blessed in [false, true] {
                for facing in 1..=4u32 {
                    let mut cpu = installed();
                    gear_range_word(&mut cpu, items << GearPatch::IAIDO_REACH_SHIFT);
                    let knight = caster_blessed(&mut cpu, &p, iaido, u32::from(CombatPatch::IAIDO_HIT_FRAME), true, blessed);
                    let kfb = cpu.rd32(knight);
                    cpu.field(kfb, p.facing_off, facing);
                    let (stage, _) = cpu.object(0x80, 0x5555);
                    cpu.wr32(p.stage_slot, stage);
                    let table = cpu.alloc(0x200);
                    cpu.wr32(p.class_table_slot, table);
                    let (wave, _) = cpu.object(0x80, 0x3333);
                    cpu.r[1] = knight;
                    for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                        cpu.r[i] = v;
                    }
                    let (mut sweeps, mut mark) = (0, None);
                    let at = cpu.run(BLOCK + CombatPatch::CAST_AT, BLOCK, END, &mut |c, pc| {
                        if pc == p.dispatch {
                            if c.r[0] == p.cell_sweep {
                                assert_eq!((c.r[1], c.r[2]), (knight, u32::from(CombatPatch::IAIDO)), "the knight's own 발도");
                                sweeps += 1;
                                c.r[0] = 1;
                            } else {
                                c.r[0] = 0;
                            }
                            return Step::Return;
                        }
                        if pc == p.new_instance {
                            c.r[0] = wave;
                            return Step::Return;
                        }
                        if pc == p.wave_ctor.1 {
                            mark = Some(c.r[3] as i32);
                            return Step::Return;
                        }
                        if pc == p.static_call {
                            return Step::Return;
                        }
                        Step::Stop
                    });
                    let r = CombatPatch::IAIDO_RADIUS + items.min(GearPatch::IAIDO_REACH_MAX) as i8;
                    let band = if blessed { r - 2 } else { 0 };
                    let tag = format!("items {items} blessed {blessed} facing {facing}");
                    assert_eq!((at, cpu.r[0], sweeps), (EXIT, 1, 1), "{tag}");
                    let (want, n) = CombatPatch::iaido_tiles(r, band, facing as u8);
                    assert_eq!(cpu.rd32(BLOCK + CombatPatch::IAIDO_N), u32::from(n), "{tag}: the count");
                    let got: Vec<(i8, i8)> = (0..u32::from(n))
                        .map(|k| (cpu.rd8(BLOCK + CombatPatch::IAIDO_TILES + 2 * k) as i8, cpu.rd8(BLOCK + CombatPatch::IAIDO_TILES + 2 * k + 1) as i8))
                        .collect();
                    assert_eq!(got, want[..usize::from(n)].to_vec(), "{tag}: the tiles");
                    let seq = match r {
                        3 => i32::from(CombatPatch::IAIDO_WAVE_SEQ),
                        _ => i32::from(CombatPatch::IAIDO_REACH_WAVE_SEQ) + i32::from(r) - 4,
                    };
                    assert_eq!(mark, blessed.then_some(-seq), "{tag}: the crescent");
                    assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
                }
            }
        }
        // The counts: radius 3 · 4 · 5 = 36 · 56 · 80; the band adds 6 · 7 · 6 beyond the disc (3 · 5 · 7 wide, 5 ahead)
        for (r, band, n) in [(3i8, 0i8, 36u8), (4, 0, 56), (5, 0, 80), (3, 1, 42), (4, 2, 63), (5, 3, 86)] {
            for f in 1..=4 {
                assert_eq!(CombatPatch::iaido_tiles(r, band, f).1, n, "radius {r} band {band} facing {f}");
            }
        }
        assert_eq!(
            CombatPatch::iaido_tiles(3, 0, 1).0[..36].iter().copied().collect::<std::collections::BTreeSet<_>>(),
            CombatPatch::disc_tiles().iter().copied().collect::<std::collections::BTreeSet<_>>(),
            "radius 3 = the shipped 발도 disc"
        );
    }

