    /// ★★ 2026-10-15 (2차 H2 검풍): a 기본공격 stage at its hit frame with the gear's RANGE_WIND — the body first (its answer is
    /// the answer), then 검기's lobe sweep (kind 4, r3 = 0) and its picture (new ak · the 검기 constructor's wrapper with
    /// (wave, knight, 1) · the stage's add). Any other frame, no bit, no gear block, a skill kind: straight to the body.
    #[test]
    fn wind_blade_fires_a_sword_wave_after_each_basic_hit() {
        let p = patch();
        let hit = u32::from(CombatPatch::BASIC_HIT_FRAME);
        let wind = GearPatch::RANGE_WIND;
        for (kind, frame, bits, fires) in [
            (0i8, hit, Some(wind), true),
            (2, hit, Some(wind | GearPatch::RANGE_LOBE), true),
            (1, hit, Some(GearPatch::RANGE_LOBE | GearPatch::IAIDO_TWICE), false),
            (1, hit, None, false),
            (0, 1, Some(wind), false),
            (0, 3, Some(wind), false),
            (5, hit, Some(wind), false),
            (-1, hit, Some(wind), false),
        ] {
            let mut cpu = installed();
            if let Some(b) = bits {
                gear_range(&mut cpu, b);
            }
            let knight = caster(&mut cpu, &p, kind, frame, true);
            let (stage, _) = cpu.object(0x80, 0x5555);
            cpu.wr32(p.stage_slot, stage);
            let table = cpu.alloc(0x200);
            cpu.wr32(p.class_table_slot, table);
            let (wave, _) = cpu.object(0x80, 0x3333);
            cpu.r[1] = knight;
            for (i, v) in [(4usize, 0x4444u32), (5, 0x5555), (6, 0x6666), (7, 0x7777)] {
                cpu.r[i] = v;
            }
            let mut order = Vec::new();
            let at = cpu.run(BLOCK + CombatPatch::CAST_AT, BLOCK, END, &mut |c, pc| {
                if pc == p.cast.1 {
                    assert_eq!(c.r[1], knight, "the body on the knight");
                    order.push("body");
                    if !fires {
                        return Step::Stop;
                    }
                    c.r[0] = 0;
                    return Step::Return;
                }
                if pc == p.dispatch {
                    if c.r[0] == p.cell_sweep {
                        assert_eq!((c.r[1], c.r[2], c.r[3]), (knight, u32::from(CombatPatch::WAVE), 0), "this.bx.h(B)Z(4), no marker");
                        order.push("sweep");
                        c.r[0] = 1;
                    } else {
                        assert_eq!((c.r[0], c.r[1], c.r[2]), (p.cell_stage_add, stage, wave), "stage.bf.d(wave)");
                        order.push("add");
                    }
                    return Step::Return;
                }
                if pc == p.new_instance {
                    assert_eq!(c.r[0], table + p.wave_class_off, "new ak");
                    order.push("new");
                    c.r[0] = wave;
                    return Step::Return;
                }
                if pc == p.wave_ctor.1 {
                    assert_eq!((c.r[1], c.r[2], c.r[3]), (wave, knight, 1), "ak.<init>(knight, 1)");
                    order.push("ctor");
                    return Step::Return;
                }
                Step::Stop
            });
            let tag = format!("kind {kind} frame {frame} bits {bits:?}");
            if fires {
                assert_eq!((at, cpu.r[0]), (EXIT, 0), "{tag}: the body's answer");
                assert_eq!(order, ["body", "sweep", "new", "ctor", "add"], "{tag}");
                assert_preserved(&cpu, &[(4, 0x4444), (5, 0x5555), (6, 0x6666), (7, 0x7777)]);
            } else {
                assert_eq!((at, cpu.r[14]), (p.cast.1, EXIT | 1), "{tag}: on to the body, the caller intact");
                assert_eq!(order, ["body"], "{tag}");
            }
        }
    }

