            let mut cpu = installed();
            let knight = caster_blessed(&mut cpu, &p, iaido as i8, u32::from(CombatPatch::IAIDO_HIT_FRAME), true, true);
            let (stage, _) = cpu.object(0x80, 0x5555);
            cpu.wr32(p.stage_slot, stage);
            let table = cpu.alloc(0x200);
            cpu.wr32(p.class_table_slot, table);
            let (wave, wfb) = cpu.object(0x80, 0x3333);
